import React, { useState } from 'react';
import { User, SystemSettings } from '../types';
import { BACKEND_SCRIPT_TEMPLATE } from '../constants';

interface LoginViewProps {
  onLogin: (user: User) => void;
  appScriptUrl: string;
  setAppScriptUrl: (url: string) => void;
  settings: SystemSettings;
}

const LoginView: React.FC<LoginViewProps> = ({ onLogin, appScriptUrl, setAppScriptUrl, settings }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [showConfig, setShowConfig] = useState(!appScriptUrl); // Only show if URL is missing
  const [showScriptModal, setShowScriptModal] = useState(false);
  const [isRegistering, setIsRegistering] = useState(false);
  const [fullName, setFullName] = useState('');
  const [position, setPosition] = useState('');
  const [isCopying, setIsCopying] = useState(false);
  const [logoError, setLogoError] = useState(false);

  // Password Change State
  const [showPasswordChange, setShowPasswordChange] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [tempUser, setTempUser] = useState<User | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!appScriptUrl) {
      setError("System Database URL is missing.");
      setShowConfig(true);
      return;
    }
    setError('');
    setIsLoading(true);

    try {
      // CRITICAL: First user registered (Bootstrapping) must be SuperAdmin
      const payload = isRegistering 
        ? { action: 'register_user', username, password, name: fullName, position: position, role: 'SuperAdmin' }
        : { action: 'login', username, password };

      const response = await fetch(appScriptUrl, {
        method: 'POST',
        body: JSON.stringify(payload)
      });

      const result = await response.json();

      if (result.status === 'success') {
          if (isRegistering) {
              setError("System Owner (SuperAdmin) created! Please log in.");
              setIsRegistering(false);
              setFullName('');
              setPosition('');
              setPassword('');
          } else {
              const rawUser = result.user;
              let safeRole: User['role'] = 'Inspector';
              const rawRole = rawUser.role ? String(rawUser.role).trim().toLowerCase() : '';

              if (rawRole === 'superadmin') safeRole = 'SuperAdmin';
              else if (rawRole === 'admin') safeRole = 'Admin';
              else if (rawRole === 'operations') safeRole = 'Operations';
              else if (rawRole === 'maintenance') safeRole = 'Maintenance';
              else if (rawRole === 'secretary') safeRole = 'Secretary'; // Explicitly handle Secretary
              else if (rawRole === 'other') safeRole = 'Other';
              else safeRole = 'Inspector';

              const normalizedUser: User = {
                  ...rawUser,
                  role: safeRole,
                  position: rawUser.position || ''
              };

              // Check for Force Password Change
              if (normalizedUser.preferences?.mustChangePassword) {
                  setTempUser(normalizedUser);
                  setShowPasswordChange(true);
                  setIsLoading(false);
                  return; // Stop login flow until password changed
              }

              onLogin(normalizedUser);
          }
      } else if (result.code === 'NO_USERS') {
          setError("New Database detected. Create the System Owner account.");
          setIsRegistering(true);
      } else {
          setError(result.message || "Authentication failed.");
      }

    } catch (err) {
      console.error("Login Error", err);
      setError("Connection failed. Check internet or Settings.");
    } finally {
      setIsLoading(false); // Only clear if not waiting for password change
    }
  };

  const handlePasswordChangeSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (newPassword.length < 4) {
          setError("Password too short (min 4 chars)");
          return;
      }
      if (newPassword !== confirmPassword) {
          setError("Passwords do not match");
          return;
      }

      setIsLoading(true);
      setError('');

      try {
          if (!tempUser) return;

          // Update password and clear the flag
          const updatedPrefs = { ...tempUser.preferences, mustChangePassword: false };

          const response = await fetch(appScriptUrl, {
              method: 'POST',
              body: JSON.stringify({
                  action: 'update_user',
                  originalUsername: tempUser.username,
                  password: newPassword,
                  preferences: updatedPrefs
              })
          });

          const result = await response.json();
          if (result.status === 'success') {
              // Proceed with login using updated user object
              const finalUser = { ...tempUser, preferences: updatedPrefs };
              onLogin(finalUser);
          } else {
              setError("Failed to update password. Try again.");
              setIsLoading(false);
          }
      } catch (err) {
          setError("Connection failed during password update.");
          setIsLoading(false);
      }
  };

  const copyScript = () => {
      navigator.clipboard.writeText(BACKEND_SCRIPT_TEMPLATE);
      setIsCopying(true);
      setTimeout(() => setIsCopying(false), 2000);
  };

  if (showPasswordChange) {
      return (
        <div className="min-h-screen w-full bg-white flex items-center justify-center p-4 font-sans text-slate-600 relative overflow-hidden">
            <div className="w-full max-w-[420px] bg-white p-2 relative z-10">
                <form onSubmit={handlePasswordChangeSubmit} className="space-y-6 animate-fadeIn">
                    <div className="text-center mb-6">
                        <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto mb-4">
                            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                        </div>
                        <h2 className="text-xl font-bold text-slate-900">Change Password</h2>
                        <p className="text-sm text-slate-500 mt-2">For your security, you must change your password before continuing.</p>
                    </div>

                    {error && (
                        <div className="p-3 bg-red-50 text-red-700 text-xs font-bold rounded-lg border border-red-200 text-center">
                            {error}
                        </div>
                    )}

                    <div className="space-y-4">
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">New Password</label>
                            <input 
                                type="password" required 
                                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-blue-500 outline-none transition-all text-slate-900 text-sm font-bold"
                                value={newPassword}
                                onChange={e => setNewPassword(e.target.value)}
                                placeholder="New Password"
                            />
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">Confirm Password</label>
                            <input 
                                type="password" required 
                                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-blue-500 outline-none transition-all text-slate-900 text-sm font-bold"
                                value={confirmPassword}
                                onChange={e => setConfirmPassword(e.target.value)}
                                placeholder="Confirm Password"
                            />
                        </div>
                    </div>

                    <button 
                        type="submit" 
                        disabled={isLoading}
                        className="w-full py-4 rounded-xl font-bold text-white shadow-lg bg-blue-600 hover:bg-blue-700 transition-all text-sm tracking-wide mt-6"
                    >
                        {isLoading ? 'Updating...' : 'Update Password & Login'}
                    </button>
                </form>
            </div>
        </div>
      );
  }

  return (
    <div className="min-h-screen w-full bg-white flex items-center justify-center p-4 font-sans text-slate-600 relative overflow-hidden">
       {/* Background accent - Subtle professional gradients matching logo tones */}
       <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-blue-50/60 blur-[100px] rounded-full pointer-events-none"></div>
       <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-emerald-50/60 blur-[100px] rounded-full pointer-events-none"></div>

       {/* Main Container */}
       <div className="w-full max-w-[420px] relative z-10 flex flex-col items-center">

          {/* Logo & Header */}
          <div className="text-center mb-8 w-full animate-fadeIn">
             <div 
                className="w-auto h-28 mx-auto mb-6 flex items-center justify-center p-2 transition-transform duration-300 hover:scale-105"
             >
                {settings.companyLogo && !logoError ? (
                    <img 
                        src={settings.companyLogo} 
                        alt="Logo" 
                        className="w-full h-full object-contain" 
                        onError={() => setLogoError(true)}
                    />
                ) : (
                    <div className="flex flex-col items-center">
                        <svg className="w-16 h-16 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"></path></svg>
                        <span className="text-2xl font-black text-slate-900 tracking-tight mt-2">JUBA</span>
                    </div>
                )}
             </div>

             <h1 className="text-2xl font-bold text-slate-900 tracking-tight">
                 {settings.companyName || 'SafetyCheck Pro'}
             </h1>
             <p className="text-sm font-medium text-slate-500 mt-1">Professional Fleet Inspection Portal</p>
          </div>

          {/* Login Form Container - Seamless White */}
          <div className="w-full bg-white p-2">
              <form onSubmit={handleSubmit} className="space-y-6">

                  {error && (
                      <div className={`p-4 rounded-lg text-xs font-bold flex items-center gap-3 border animate-fadeIn ${error.includes("created") || error.includes("success") ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                          <div className={`w-2 h-2 rounded-full shrink-0 ${error.includes("created") ? 'bg-green-500' : 'bg-red-500'}`}></div>
                          <span className="flex-1">{error}</span>
                      </div>
                  )}

                  {isRegistering && (
                      <div className="space-y-4 animate-fadeIn bg-slate-50 p-6 rounded-xl border border-slate-100 shadow-inner">
                        <div className="flex items-center gap-2 border-b border-slate-200 pb-2 mb-3">
                            <div className="bg-amber-100 text-amber-700 p-1 rounded">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.38-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z"></path></svg>
                            </div>
                            <h3 className="text-xs font-black text-slate-700 uppercase tracking-wide">System Owner Setup</h3>
                        </div>
                        <p className="text-[10px] text-slate-500 leading-tight">You are creating the first account (SuperAdmin). You will have full access to settings and subscriptions.</p>
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">Full Name</label>
                            <input 
                                type="text" required 
                                className="w-full px-4 py-3 bg-white border border-slate-300 rounded-lg focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none transition-all text-slate-900 text-sm font-medium placeholder-slate-400"
                                placeholder="e.g. John Doe"
                                value={fullName}
                                onChange={e => setFullName(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">Position</label>
                            <input 
                                type="text" required 
                                className="w-full px-4 py-3 bg-white border border-slate-300 rounded-lg focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none transition-all text-slate-900 text-sm font-medium placeholder-slate-400"
                                placeholder="e.g. Fleet Director"
                                value={position}
                                onChange={e => setPosition(e.target.value)}
                            />
                        </div>
                      </div>
                  )}

                  <div className="space-y-5">
                      <div className="group">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1 transition-colors group-focus-within:text-emerald-700">Username</label>
                          <div className="relative">
                              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-600 transition-colors">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
                              </span>
                              <input 
                                  type="text" required 
                                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all text-slate-900 text-sm font-bold placeholder-slate-400 shadow-sm"
                                  placeholder="Enter username"
                                  value={username}
                                  onChange={e => setUsername(e.target.value)}
                              />
                          </div>
                      </div>

                      <div className="group">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1 transition-colors group-focus-within:text-emerald-700">Password</label>
                          <div className="relative">
                              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-emerald-600 transition-colors">
                                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                              </span>
                              <input 
                                  type="password" required 
                                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all text-slate-900 text-sm font-bold placeholder-slate-400 shadow-sm"
                                  placeholder="••••••••"
                                  value={password}
                                  onChange={e => setPassword(e.target.value)}
                              />
                          </div>
                      </div>
                  </div>

                  <div className="pt-4">
                      <button 
                          type="submit" 
                          disabled={isLoading}
                          className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all text-sm tracking-wide transform active:scale-[0.98] border border-transparent
                              ${isLoading 
                                ? 'bg-slate-400 cursor-wait' 
                                : isRegistering 
                                    ? 'bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-500 hover:to-blue-600 shadow-blue-200' 
                                    : 'bg-gradient-to-r from-emerald-700 to-emerald-600 hover:from-emerald-600 hover:to-emerald-500 shadow-emerald-200'
                              }
                          `}
                      >
                          {isLoading ? (
                              <div className="flex items-center justify-center gap-2">
                                  <svg className="animate-spin h-4 w-4" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                  <span>VERIFYING...</span>
                              </div>
                          ) : (
                              isRegistering ? 'CREATE SYSTEM OWNER' : 'SECURE LOGIN'
                          )}
                      </button>
                  </div>

                  {isRegistering && (
                      <button 
                        type="button" 
                        onClick={() => setIsRegistering(false)}
                        className="w-full py-2 text-xs font-bold text-slate-500 hover:text-slate-800 uppercase tracking-wider transition-colors"
                      >
                          Cancel Registration
                      </button>
                   )}
              </form>

              {/* Configure Link */}
              {!appScriptUrl && !isRegistering && (
                  <div className="mt-12 text-center">
                      <button 
                        type="button" 
                        onClick={() => setShowConfig(!showConfig)}
                        className="group flex items-center justify-center gap-2 mx-auto px-4 py-2 rounded-full bg-slate-100 hover:bg-white border border-slate-200 hover:border-slate-300 shadow-sm transition-all"
                      >
                          <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></span>
                          <span className="text-[10px] text-slate-500 group-hover:text-slate-800 font-bold uppercase tracking-widest">Connect Database</span>
                      </button>
                  </div>
              )}
          </div>

          {/* Config Panel */}
          {showConfig && (
              <div className="w-full mt-6 bg-white border border-slate-200 p-6 rounded-2xl animate-fadeIn shadow-xl relative z-20">
                  <h4 className="text-[10px] font-black text-slate-400 mb-4 uppercase tracking-widest flex items-center gap-2">
                      <svg className="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                      Database Connection
                  </h4>
                  <input 
                      type="text" 
                      value={appScriptUrl} 
                      onChange={e => setAppScriptUrl(e.target.value)}
                      placeholder="https://script.google.com/macros/s/..."
                      className="w-full p-3 bg-slate-50 border border-slate-300 rounded-lg text-xs font-mono text-blue-600 mb-4 focus:outline-none focus:border-blue-500 shadow-inner"
                  />
                  <button 
                      onClick={() => setShowScriptModal(true)}
                      className="w-full py-3 bg-slate-800 text-white text-xs font-bold rounded-lg hover:bg-slate-700 transition-colors shadow-sm flex items-center justify-center gap-2"
                  >
                      <svg className="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                      View Setup Instructions
                  </button>
              </div>
          )}
       </div>

       {/* Script Modal */}
       {showScriptModal && (
         <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full flex flex-col max-h-[85vh] overflow-hidden border border-slate-200">
                <div className="p-5 bg-slate-50 flex justify-between items-center border-b border-slate-200">
                    <h3 className="font-bold text-lg text-slate-800">Backend Setup Guide</h3>
                    <button onClick={() => setShowScriptModal(false)} className="text-slate-400 hover:text-slate-700 transition p-2 hover:bg-slate-200 rounded-lg">✕</button>
                </div>
                <div className="p-8 overflow-y-auto bg-white">
                    <div className="prose prose-sm max-w-none text-slate-600 mb-6">
                        <ol className="list-decimal pl-4 space-y-2 font-medium">
                            <li>Create a new <strong>Google Sheet</strong>.</li>
                            <li>Go to <strong>Extensions &gt; Apps Script</strong>.</li>
                            <li>Paste the code below entirely, replacing any existing code.</li>
                            <li>Click <strong>Deploy &gt; New Deployment</strong>.</li>
                            <li>Select type: <strong>Web App</strong>.</li>
                            <li>Set "Execute as" to <strong>Me</strong>.</li>
                            <li>Set "Who has access" to <strong>Anyone</strong>.</li>
                            <li>Copy the resulting Web App URL and paste it into the login screen.</li>
                        </ol>
                    </div>
                    <div className="relative group">
                        <pre className="bg-slate-900 p-6 rounded-xl text-[10px] font-mono text-emerald-400 overflow-x-auto border border-slate-800 shadow-inner h-64">
                            {BACKEND_SCRIPT_TEMPLATE}
                        </pre>
                        <button 
                            onClick={copyScript}
                            className="absolute top-4 right-4 px-4 py-2 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-500 shadow-lg transition-all transform active:scale-95"
                        >
                            {isCopying ? 'COPIED!' : 'COPY CODE'}
                        </button>
                    </div>
                </div>
            </div>
         </div>
       )}
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect } from 'react';
import { User, ValidationLists, SystemSettings } from '../types';
import AutocompleteInput from '../components/ui/AutocompleteInput';

interface UserManagementViewProps {
    currentUser: User;
    appScriptUrl: string;
    showToast: (msg: string, type: 'success' | 'error' | 'info') => void;
    validationLists: ValidationLists;
    settings?: SystemSettings;
}

const UserManagementView: React.FC<UserManagementViewProps> = ({ currentUser, appScriptUrl, showToast, validationLists, settings }) => {
    // User type extended with password for sharing logic
    const [users, setUsers] = useState<(User & {password?: string})[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    // View State: 'list' or 'form'
    const [viewMode, setViewMode] = useState<'list' | 'form'>('list');
    const [isEditing, setIsEditing] = useState(false);
    const [originalUsername, setOriginalUsername] = useState('');

    // Form State
    const [formData, setFormData] = useState<{
        name: string;
        username: string;
        password: string;
        role: 'SuperAdmin' | 'Admin' | 'Inspector' | 'Operations' | 'Maintenance' | 'Other' | 'Secretary';
        position: string;
    }>({
        name: '',
        username: '',
        password: '',
        role: 'Inspector',
        position: ''
    });
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Only SuperAdmin can create other SuperAdmins
    const isSuperAdmin = currentUser.role === 'SuperAdmin';

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        if (!appScriptUrl) return;
        setIsLoading(true);
        try {
            const response = await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({ action: 'get_users' })
            });
            const result = await response.json();
            if (result.status === 'success' && Array.isArray(result.users)) {
                let fetchedUsers = result.users;

                // SECURITY: Hide SuperAdmins from regular Admins
                if (!isSuperAdmin) {
                    fetchedUsers = fetchedUsers.filter((u: User) => u.role !== 'SuperAdmin');
                }

                setUsers(fetchedUsers);
            }
        } catch (e) {
            console.error(e);
            showToast("Failed to load users", 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDelete = async (username: string) => {
        if (!window.confirm(`Are you sure you want to remove user "${username}"?`)) return;

        setIsLoading(true);
        try {
            const response = await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({ action: 'delete_user', username })
            });
            const result = await response.json();
            if (result.status === 'success') {
                showToast("User removed successfully", 'success');
                fetchUsers();
            } else {
                showToast(result.message || "Failed to delete user", 'error');
            }
        } catch (e) {
            showToast("Connection failed", 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleEdit = (user: User) => {
        setFormData({
            name: user.name,
            username: user.username,
            role: user.role as any,
            position: user.position || '',
            password: '' // Leave empty for edit
        });
        setOriginalUsername(user.username);
        setIsEditing(true);
        setViewMode('form');
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.name || !formData.username) {
            showToast("Please fill in required fields.", 'error');
            return;
        }

        if (!isEditing && !formData.password) {
             showToast("Password is required for new users.", 'error');
             return;
        }

        setIsSubmitting(true);

        try {
            // Find current user's existing preferences to preserve them, OR set default
            const existingUser = users.find(u => u.username === originalUsername);
            let prefs = existingUser?.preferences || {
                emailNotifications: true,
                notifyGeneral: true,
                notifyPetroleum: true,
                notifyPetroleumV2: true,
                notifyAcid: true,
                mustChangePassword: false
            };

            // If creating new user, OR changing password for existing user, force password change on next login
            if (!isEditing || (formData.password && formData.password.trim() !== '')) {
                prefs = { ...prefs, mustChangePassword: true };
            }

            const payload: any = {
                action: isEditing ? 'update_user' : 'register_user',
                ...formData,
                preferences: prefs
            };

            if (isEditing) {
                payload.originalUsername = originalUsername;
            }

            const response = await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify(payload)
            });
            const result = await response.json();

            if (result.status === 'success') {
                const msg = isEditing 
                    ? (formData.password ? "User updated. They must change password on next login." : "User updated successfully")
                    : "User created. They must change password on first login.";

                showToast(msg, 'success');
                setViewMode('list');
                setFormData({ name: '', username: '', password: '', role: 'Inspector', position: '' });
                setIsEditing(false);
                fetchUsers();
            } else {
                showToast(result.message || "Operation failed", 'error');
            }
        } catch (e) {
            showToast("Connection failed", 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    // Robust Fallback Copy Mechanism
    const fallbackCopyTextToClipboard = (text: string) => {
        const textArea = document.createElement("textarea");
        textArea.value = text;

        // Avoid scrolling to bottom
        textArea.style.top = "0";
        textArea.style.left = "0";
        textArea.style.position = "fixed";
        textArea.style.opacity = "0";

        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();

        try {
            const successful = document.execCommand('copy');
            if (successful) {
                showToast("Details copied to clipboard (Fallback)", 'success');
            } else {
                showToast("Unable to copy details. Please copy manually.", 'error');
            }
        } catch (err) {
            showToast("Unable to copy details. Please copy manually.", 'error');
        }

        document.body.removeChild(textArea);
    };

    const handleShareUser = async (user: User & {password?: string}) => {
        const companyName = settings?.companyName || 'SafetyCheck Pro';
        const webUrl = settings?.webAppUrl || window.location.origin + window.location.pathname;
        const apkUrl = settings?.mobileApkLink || 'Contact Admin for APK';

        const title = "System Access Credentials";
        const text = `
${companyName.toUpperCase()} - ACCESS CREDENTIALS
----------------------------------
Here are your login details for the digital inspection system.

Name: ${user.name}
Role: ${user.role}
${user.position ? `Position: ${user.position}` : ''}

LOGIN DETAILS:
Username: ${user.username}
Password: ${user.password || '****'} (Change on first login)

ACCESS LINKS:
💻 Web Portal:
${webUrl}

📱 Android App:
${apkUrl}

Please keep these credentials secure.
----------------------------------
`.trim();

        if (navigator.share) {
            try {
                // Pass text ONLY to ensure consistent behavior across platforms (avoiding URL-only shares)
                await navigator.share({
                    title: title,
                    text: text
                });
                showToast("Credentials shared successfully via System", 'success');
            } catch (err) {
                // User cancelled or API failed
                // Attempt Clipboard Fallback
                try {
                    await navigator.clipboard.writeText(text);
                    showToast("Share cancelled. Details copied to clipboard.", 'info');
                } catch (clipboardErr) {
                    fallbackCopyTextToClipboard(text);
                }
            }
        } else {
            // Fallback for browsers without share support
            try {
                await navigator.clipboard.writeText(text);
                showToast("Credentials copied to clipboard!", 'success');
            } catch (err) {
                fallbackCopyTextToClipboard(text);
            }
        }
    };

    // Access Control: Must be Admin or SuperAdmin
    const canManage = currentUser.role && (currentUser.role === 'Admin' || currentUser.role === 'SuperAdmin');

    if (!canManage) {
        return <div className="p-8 text-center text-red-600 font-bold">Access Denied. Admin Privileges Required.</div>;
    }

    // --- FORM VIEW (CREATE & EDIT) ---
    if (viewMode === 'form') {
        return (
            <div className="max-w-lg mx-auto animate-fadeIn py-4 px-2 sm:px-0">
                <button 
                    onClick={() => setViewMode('list')}
                    className="mb-4 flex items-center gap-2 text-gray-500 hover:text-gray-800 transition-colors text-xs font-bold uppercase tracking-wider"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                    Back to List
                </button>

                <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
                    <div className="bg-slate-50 px-6 py-4 border-b border-gray-100 flex items-center justify-between">
                        <h2 className="text-lg font-black text-slate-800 tracking-tight">
                            {isEditing ? 'Edit User Details' : 'Create New User'}
                        </h2>
                        <div className="w-8 h-8 bg-white rounded-lg shadow-sm flex items-center justify-center text-blue-600 border border-gray-100">
                             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                        </div>
                    </div>

                    <div className="p-6">
                        <form onSubmit={handleSubmit} className="space-y-4">

                            {/* Full Name */}
                            <div className="space-y-1">
                                <AutocompleteInput
                                    label="Full Name"
                                    value={formData.name}
                                    onChange={v => setFormData({...formData, name: v})}
                                    options={validationLists.inspectors} 
                                    isTitleCase={true}
                                    placeholder="e.g. John Doe"
                                />
                            </div>

                            {/* Position & Role (Side-by-Side) */}
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <AutocompleteInput
                                        label="Position"
                                        value={formData.position}
                                        onChange={v => setFormData({...formData, position: v})}
                                        options={validationLists.positions} 
                                        isTitleCase={true}
                                        placeholder="Job Title"
                                    />
                                </div>
                                <div>
                                    <div className="flex justify-between items-center mb-1.5">
                                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide">System Role</label>
                                        {!isSuperAdmin && (
                                            <span className="text-[9px] text-amber-600 font-medium flex items-center gap-1 bg-amber-50 px-1.5 py-0.5 rounded border border-amber-100">
                                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                                                Restricted
                                            </span>
                                        )}
                                    </div>
                                    <select 
                                        className="w-full p-3.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-gray-50 text-sm font-medium transition-colors text-gray-800"
                                        value={formData.role}
                                        onChange={e => setFormData({...formData, role: e.target.value as any})}
                                    >
                                        <option value="Inspector">Inspector</option>
                                        <option value="Operations">Operations</option>
                                        <option value="Maintenance">Maintenance</option>
                                        <option value="Secretary">Secretary</option>
                                        <option value="Other">Other</option>
                                        <option value="Admin">Admin</option>
                                        {isSuperAdmin && <option value="SuperAdmin">SuperAdmin</option>}
                                    </select>
                                </div>
                            </div>

                            {/* Username & Password (Side-by-Side) */}
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5 tracking-wide">Username</label>
                                    <input 
                                        type="text" required 
                                        className="w-full p-3.5 border rounded-lg outline-none font-medium transition-all text-sm bg-gray-50 border-gray-200 text-gray-800 focus:ring-2 focus:ring-blue-500"
                                        value={formData.username}
                                        onChange={e => setFormData({...formData, username: e.target.value})}
                                        placeholder="jdoe"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5 tracking-wide">
                                        Password {isEditing && <span className="text-gray-400 font-normal normal-case">(Optional)</span>}
                                    </label>
                                    <input 
                                        type="password" 
                                        required={!isEditing}
                                        className="w-full p-3.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-gray-50 text-gray-800 placeholder-gray-400 font-medium transition-all text-sm"
                                        value={formData.password}
                                        onChange={e => setFormData({...formData, password: e.target.value})}
                                        placeholder={isEditing ? "Leave blank to keep current" : "••••"}
                                    />
                                </div>
                            </div>

                            <div className="p-3 bg-amber-50 rounded-lg border border-amber-100 flex items-start gap-2">
                                <svg className="w-4 h-4 text-amber-600 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                                <p className="text-[10px] text-amber-800">
                                    Setting a password will prompt the user to change it upon their next login for security.
                                </p>
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button 
                                    type="button" 
                                    onClick={() => setViewMode('list')}
                                    className="flex-1 py-3 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 font-bold rounded-xl transition text-sm"
                                >
                                    Cancel
                                </button>
                                <button 
                                    type="submit"
                                    disabled={isSubmitting}
                                    className="flex-1 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-md transition disabled:bg-blue-400 text-sm flex items-center justify-center gap-2"
                                >
                                    {isSubmitting ? 'Saving...' : isEditing ? 'Update User' : 'Create User'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        );
    }

    // --- LIST VIEW ---
    return (
        <div className="max-w-6xl mx-auto space-y-6 animate-fadeIn">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                    <span className="p-2 bg-purple-100 text-purple-700 rounded-lg">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"></path></svg>
                    </span>
                    User Management
                </h2>
                <div className="flex gap-3 w-full sm:w-auto">
                     <button 
                        onClick={fetchUsers} 
                        className="flex-1 sm:flex-none justify-center px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 flex items-center gap-2"
                    >
                        <svg className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                        Refresh
                    </button>
                    <button 
                        onClick={() => {
                            setFormData({ name: '', username: '', password: '', role: 'Inspector', position: '' });
                            setIsEditing(false);
                            setViewMode('form');
                        }}
                        className="flex-1 sm:flex-none justify-center px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg shadow-md flex items-center gap-2 transition"
                    >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                        Add User
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm whitespace-nowrap">
                        <thead className="bg-gray-50 text-xs font-bold text-gray-500 uppercase border-b border-gray-200">
                            <tr>
                                <th className="px-4 py-3">Name / Position</th>
                                <th className="px-4 py-3">Username</th>
                                <th className="px-4 py-3">Role</th>
                                <th className="px-4 py-3">Last Login</th>
                                <th className="px-4 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {users.length === 0 ? (
                                <tr><td colSpan={5} className="p-8 text-center text-gray-500">{isLoading ? 'Loading users...' : 'No users found.'}</td></tr>
                            ) : (
                                users.map((u, i) => (
                                    <tr key={i} className="hover:bg-gray-50">
                                        <td className="px-4 py-3">
                                            <div className="font-bold text-gray-900">{u.name}</div>
                                            <div className="text-xs text-gray-500">{u.position}</div>
                                        </td>
                                        <td className="px-4 py-3 font-mono text-gray-600">{u.username}</td>
                                        <td className="px-4 py-3">
                                            <span className={`px-2 py-1 rounded text-xs font-bold 
                                                ${u.role === 'SuperAdmin' ? 'bg-black text-white' : 
                                                  u.role === 'Admin' ? 'bg-purple-100 text-purple-700' : 
                                                  u.role === 'Operations' ? 'bg-blue-100 text-blue-700' :
                                                  u.role === 'Maintenance' ? 'bg-orange-100 text-orange-700' :
                                                  u.role === 'Secretary' ? 'bg-indigo-100 text-indigo-700' :
                                                  u.role === 'Other' ? 'bg-gray-100 text-gray-700' :
                                                  'bg-green-100 text-green-700'}`}>
                                                {u.role}
                                            </span>
                                        </td>
                                        <td className="px-4 py-3 text-gray-500 text-xs">
                                            {u.lastLogin ? new Date(u.lastLogin).toLocaleDateString() : 'Never'}
                                        </td>
                                        <td className="px-4 py-3 text-right">
                                            {u.username !== currentUser.username && (
                                                <div className="flex justify-end gap-2">
                                                    {/* Native Share - Increased Hit Area */}
                                                    <button 
                                                        onClick={() => handleShareUser(u)}
                                                        title="Share Access Credentials & Links"
                                                        className="p-2 text-indigo-600 hover:bg-indigo-50 rounded border border-transparent hover:border-indigo-200 transition-colors"
                                                    >
                                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"></path></svg>
                                                    </button>

                                                    {/* Edit */}
                                                    <button 
                                                        onClick={() => handleEdit(u)}
