import React, { useState } from 'react';
import AutocompleteInput from './AutocompleteInput';
import { ValidationLists } from '../../types';

interface RequestInspectionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    validationLists: ValidationLists;
    currentUserRole: string;
}

const RequestInspectionModal: React.FC<RequestInspectionModalProps> = ({ 
    isOpen, onClose, onSubmit, validationLists, currentUserRole 
}) => {
    if (!isOpen) return null;

    const [truckNo, setTruckNo] = useState('');
    const [trailerNo, setTrailerNo] = useState('');
    const [type, setType] = useState('General');
    const [priority, setPriority] = useState('Normal');
    const [reason, setReason] = useState('');
    const [inspector, setInspector] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [errors, setErrors] = useState<Record<string, boolean>>({});

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const newErrors: Record<string, boolean> = {};

        // Validation: Strict Check against existing lists
        // Truck
        const truckExists = validationLists.trucks.some(t => t.trim().toLowerCase() === truckNo.trim().toLowerCase());
        if (!truckNo || !truckExists) newErrors.truckNo = true;

        // Trailer (Optional but strict if entered)
        if (trailerNo) {
            const trailerExists = validationLists.trailers.some(t => t.trim().toLowerCase() === trailerNo.trim().toLowerCase());
            if (!trailerExists) newErrors.trailerNo = true;
        }

        // Inspector (Optional but strict if entered)
        if (inspector) {
             const inspectorExists = validationLists.inspectors.some(i => i.trim().toLowerCase() === inspector.trim().toLowerCase());
             if (!inspectorExists) newErrors.inspector = true;
        }

        if (!reason) newErrors.reason = true;

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            return;
        }

        setIsSubmitting(true);
        try {
            await onSubmit({ truckNo, trailerNo, type, priority, reason, assignedInspector: inspector });
            onClose();
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden transform transition-all scale-100 border border-slate-200">

