                                    placeholder="Select Truck"
                                    error={errors.truckNo}
                                />
                                {errors.truckNo && <p className="text-[10px] text-red-500 font-bold mt-1">Must be an existing truck</p>}
                            </div>
                            <div>
                                <AutocompleteInput 
                                    label="Trailer Reg No" 
                                    value={trailerNo}
                                    onChange={(v) => { setTrailerNo(v); setErrors(prev => ({...prev, trailerNo: false})); }}
                                    options={validationLists.trailers}
