            damage: formData.photoDamage
        },
        companyName: settings.companyName,
        companyLogo: settings.companyLogo
    };

    const rowData = targetHeaders.map(header => {
        if (header === 'id') return recordId;
        const val = (formData as any)[header];
        return (val === null || val === undefined) ? "" : val;
    });

    const payload = {
        sheet: targetSheet,
        action: "create",
        row: rowData,
        headers: targetHeaders,
        id: recordId,
        reportData: reportData
    };

    // --- ROBUST SUBMISSION LOGIC ---
    // 1. Check strict offline first
    if (!navigator.onLine) {
        addToQueue(payload);
        clearDraft(activeModule);
        setSubmissionStatus('offline_saved');
        setTimeout(() => {
             startFreshInspection(activeModule); 
             setViewMode('dashboard');
             setSubmissionStatus('idle');
             showToast("Offline Mode: Report Saved. Will sync when online.", 'info');
        }, 2000);
        return;
    }

    // 2. Attempt online submission with timeout handling
    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 15000); // 15s hard timeout for poor connections

        await fetch(appScriptUrl, {
            method: 'POST',
            body: JSON.stringify(payload),
            mode: 'no-cors', 
            headers: { 'Content-Type': 'text/plain' },
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        clearDraft(activeModule);
        setSubmissionStatus('success');

        setTimeout(() => {
             startFreshInspection(activeModule); 
             setViewMode('dashboard');
             setSubmissionStatus('idle');
             fetchHistory(true); 
             fetchNotifications();
             showToast("Inspection Submitted & Email Sent!", 'success');
        }, 2500);

    } catch (error: any) {
        console.error("Submission Error", error);

        // 3. Fallback to Offline Queue on ANY failure (Network or Timeout)
        addToQueue(payload);
        clearDraft(activeModule); 
        setSubmissionStatus('offline_saved');

        const isTimeout = error.name === 'AbortError';
        const msg = isTimeout ? "Slow Network detected. Saved to offline queue." : "Network Error. Report queued for auto-sync.";

        setTimeout(() => {
             startFreshInspection(activeModule); 
             setViewMode('dashboard');
             setSubmissionStatus('idle');
             showToast(msg, 'warning');
        }, 2500);
    }
  };

  const handlePrint = () => window.print();
  const handleQuickPrint = (item: InspectionData) => {
      setSelectedReportData(item);
      setTimeout(() => window.print(), 500);
  };
  const handleViewReport = (item: InspectionData | null) => {
    setSelectedReportData(item);
    setIsReportModalOpen(true);
  };

  const handleNotificationAction = (id: string, onNavigate?: (module: string) => void) => {
      handleMarkNotificationRead(id, (module) => {
          // Special handling for request inspection start links
          // Link format: request:start_inspection|type|truck|trailer|requester|reason
          const targetNotification = notifications.find(n => n.id === id);
          if (targetNotification?.actionLink?.startsWith('request:start_inspection')) {
              const parts = targetNotification.actionLink.split('|');
              const type = parts[1].toLowerCase();
              const truck = parts[2];
              const trailer = parts[3];
              const requester = parts[4];
              const reason = parts[5];

              let targetMod = 'general';
              if (type.includes('petroleum_v2')) targetMod = 'petroleum_v2';
              else if (type.includes('petroleum')) targetMod = 'petroleum';
              else if (type.includes('acid')) targetMod = 'acid';

              setActiveModule(targetMod);

              // Professionally pre-fill the form and add the request note
              startFreshInspection(targetMod, {
                  truckNo: truck,
                  trailerNo: trailer,
                  remarks: `** AD-HOC REQUEST **\nInitiated by: ${requester}\nReason: ${reason}`
              });

              showToast("Inspection started from request.", 'info');
          } else {
              // Standard navigation
              if (onNavigate) onNavigate(module);
              else {
                  setActiveModule(module);
                  setViewMode('dashboard');
              }
          }
      });
  };

  // --- RENDER ---
  if (!currentUser) {
      return (
          <LoginView 
            onLogin={handleLogin} 
            appScriptUrl={appScriptUrl}
            setAppScriptUrl={setAppScriptUrl}
            settings={settings}
          />
      );
  }

  const canAcknowledge = ['Admin', 'Maintenance', 'Inspector', 'SuperAdmin'].includes(currentUser.role || '');
  const isSuperAdmin = currentUser.role === 'SuperAdmin';
  // Maintenance Check: If active AND not SuperAdmin, show Overlay
  const showMaintenanceOverlay = settings.maintenanceMode && !isSuperAdmin;

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 relative">
      <SubmissionOverlay status={submissionStatus} />

      {/* GLOBAL MAINTENANCE LOCKOUT */}
      <MaintenanceOverlay 
          isActive={showMaintenanceOverlay} 
          message={settings.maintenanceMessage || ''} 
          onLogout={handleLogout}
      />

      {/* SMART NETWORK & SYNC INDICATOR */}
      <NetworkStatus 
          queueLength={offlineQueue.length} 
          isSyncing={isSyncing} 
          isPoorConnection={isPoorConnection}
          onRetry={syncOfflineQueue}
      />

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <RequestInspectionModal
          isOpen={isRequestModalOpen}
          onClose={() => setIsRequestModalOpen(false)}
          onSubmit={handleRequestInspectionSubmit}
          validationLists={validationLists}
          currentUserRole={currentUser.role || ''}
      />

      <InspectionStartModal 
          isOpen={isStartModalOpen}
          onClose={() => setIsStartModalOpen(false)}
          moduleName={targetModuleForStart || 'General'}
          hasDraft={!!targetModuleForStart && hasDraft(targetModuleForStart)}
          onStartNew={() => {
              if (targetModuleForStart) startFreshInspection(targetModuleForStart);
              setIsStartModalOpen(false);
          }}
          onResume={() => {
              if (targetModuleForStart) resumeDraftInspection(targetModuleForStart);
              setIsStartModalOpen(false);
          }}
      />

      {upgradeFeature && <UpgradeModal featureName={upgradeFeature} onClose={() => setUpgradeFeature(null)} />}

      {isProfileModalOpen && currentUser && (
          <ProfileModal 
              user={currentUser}
              appScriptUrl={appScriptUrl}
              onClose={() => setIsProfileModalOpen(false)}
              showToast={showToast}
              onUpdateSuccess={(updatedUser) => {
                   setCurrentUser(updatedUser);
                   localStorage.setItem('safetyCheck_user', JSON.stringify(updatedUser));
              }}
          />
      )}

      {/* Report Preview Modal (Client Side View Only) */}
      {isReportModalOpen && (
          <ReportViewerModal 
            onClose={() => setIsReportModalOpen(false)} 
            onPrint={handlePrint}
            title="Inspection Report"
          >
               <div className="print-only-container">
                    {activeModule === 'petroleum' ? (
                        <PrintablePetroleumReport data={selectedReportData || formInitialData} settings={settings} />
                    ) : activeModule === 'petroleum_v2' ? (
                        <PrintablePetroleumV2Report data={selectedReportData || formInitialData} settings={settings} />
                    ) : activeModule === 'acid' ? (
                        <PrintableAcidReport data={selectedReportData || formInitialData} settings={settings} />
                    ) : (
                        <PrintableGeneralReport data={selectedReportData || formInitialData} settings={settings} />
                    )}
               </div>
          </ReportViewerModal>
      )}

      {/* Hidden print element */}
      <div className="print-only hidden p-0 bg-white">
         {activeModule === 'petroleum' ? (
             <PrintablePetroleumReport data={selectedReportData || formInitialData} settings={settings} />
         ) : activeModule === 'petroleum_v2' ? (
             <PrintablePetroleumV2Report data={selectedReportData || formInitialData} settings={settings} />
         ) : activeModule === 'acid' ? (
             <PrintableAcidReport data={selectedReportData || formInitialData} settings={settings} />
         ) : (
             <PrintableGeneralReport data={selectedReportData || formInitialData} settings={settings} />
         )}
      </div>

      <div className="relative z-10 bg-gray-50 min-h-screen">
          <Sidebar 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
            activeModule={activeModule}
            onSelectModule={(m) => {
                setActiveModule(m);
                setViewMode('dashboard');
            }}
            onLockedItemClick={(feature) => setUpgradeFeature(feature)}
            settings={settings}
            user={currentUser}
            onLogout={handleLogout}
            onEditProfile={() => setIsProfileModalOpen(true)}
            subscription={subscription} 
            onRequestInspection={() => setIsRequestModalOpen(true)} // Pass trigger
          />

          <div className="lg:pl-64 min-h-screen flex flex-col transition-all duration-300">
            {/* Global Subscription Alert */}
            <SubscriptionAlert 
                subscription={subscription} 
                user={currentUser} 
                onManage={() => { setActiveModule('settings'); setViewMode('dashboard'); }}
            />

            <header className="bg-emerald-950 border-b border-emerald-900 sticky top-0 z-40 shadow-sm">
              <div className="px-4 py-3 flex justify-between items-center text-white">
                <div className="flex items-center gap-3">
                    <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1 hover:bg-slate-800 rounded">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"></path></svg>
                    </button>
                    <div className="flex flex-col">
                        <h1 className="text-lg md:text-xl font-bold flex items-center gap-2">
                            {activeModule === 'overview' ? 'Executive Dashboard' : 
                            activeModule === 'petroleum' ? 'Petroleum V1' : 
                            activeModule === 'petroleum_v2' ? 'Petroleum V2' : 
                            activeModule === 'acid' ? 'Acid' : 
                            activeModule === 'settings' ? 'System' :
                            activeModule === 'users' ? 'Users' :
                            activeModule === 'support' ? 'Support Hub' :
                            activeModule === 'maintenance' ? 'Superadmin Console' :
                            'SafetyCheck'}
                        </h1>
                        {isBackgroundFetching && (
                            <div className="flex items-center gap-1.5 text-[10px] text-emerald-300 animate-pulse">
                                Checking for updates...
                            </div>
                        )}
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* Sync Status Button - Desktop Only (Mobile uses floating banner) */}
                    {offlineQueue.length > 0 && (
                        <button
                            onClick={syncOfflineQueue}
                            disabled={isSyncing} 
                            className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold transition-all shadow-sm
                                ${isSyncing 
                                    ? 'bg-blue-600 text-white cursor-wait' 
                                    : isPoorConnection 
                                        ? 'bg-red-500 text-white hover:bg-red-600 animate-pulse' 
                                        : 'bg-amber-500 text-white hover:bg-amber-600'}
                            `}
                        >
                            {isSyncing ? (
                                <>
                                    <svg className="animate-spin w-3 h-3" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                    <span>Syncing...</span>
                                </>
                            ) : (
                                <span>{isPoorConnection ? 'Retry Upload' : `Pending (${offlineQueue.length})`}</span>
                            )}
                        </button>
                    )}

                    <NotificationCenter 
                        notifications={notifications}
                        onMarkAsRead={(id) => handleNotificationAction(id, (m) => { setActiveModule(m); setViewMode('dashboard'); })}
                        onDismiss={handleDismissNotification}
                        onClearAll={handleClearAllNotifications}
                        onAcknowledge={handleGlobalAcknowledge}
                        canAcknowledge={canAcknowledge}
                    />
                </div>
              </div>
            </header>

            {viewMode === 'form' ? (
                <InspectionFormView 
                    initialData={formInitialData}
                    activeModule={activeModule}
                    validationLists={validationLists}
                    settings={settings}
                    onSaveDraft={handleExitForm} 
                    onExit={() => handleExitForm()} 
                    onSubmit={handleGoogleSheetSubmit}
                    submissionStatus={submissionStatus}
                    onViewReport={handleViewReport}
                />
            ) : (
                <main className="flex-1 p-4 md:p-6 lg:p-8 max-w-6xl mx-auto w-full">
                  {activeModule === 'overview' && (
                      <OverviewDashboard 
                          appScriptUrl={appScriptUrl}
                          onNavigate={(module) => { setActiveModule(module); setViewMode('dashboard'); }}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'settings' && (
                      <SettingsView 
                          settings={settings}
                          setSettings={setSettings}
                          appScriptUrl={appScriptUrl}
                          setAppScriptUrl={setAppScriptUrl}
                          handleSaveSettings={handleSaveSettings}
                          isSavingSettings={isSavingSettings}
                          showToast={showToast}
                          user={currentUser} 
                      />
                  )}

                  {activeModule === 'users' && (
                      <UserManagementView 
                          currentUser={currentUser}
                          appScriptUrl={appScriptUrl}
                          showToast={showToast}
                          validationLists={validationLists}
                          settings={settings}
                      />
                  )}

                  {activeModule === 'support' && (
                      <SupportView 
                          appScriptUrl={appScriptUrl}
                          currentUser={currentUser}
                          showToast={showToast}
                          settings={settings}
                          validationLists={validationLists}
                      />
                  )}

                  {activeModule === 'maintenance' && isSuperAdmin && (
                      <MaintenanceView 
                          user={currentUser}
                          appScriptUrl={appScriptUrl}
                          settings={settings}
                          onSettingsUpdate={(newS) => setSettings(p => ({...p, ...newS}))}
                          showToast={showToast}
                      />
                  )}

                  {activeModule === 'general' && (
                      <GeneralDashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('general')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'petroleum' && (
                      <PetroleumDashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('petroleum')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'petroleum_v2' && (
                      <PetroleumV2Dashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('petroleum_v2')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'acid' && (
                      <AcidDashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('acid')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}
                </main>
            )}
          </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import AutocompleteInput from './AutocompleteInput';
import { ValidationLists } from '../../types';

interface RequestInspectionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    validationLists: ValidationLists;
    currentUserRole: string;
}

const RequestInspectionModal: React.FC<RequestInspectionModalProps> = ({ 
    isOpen, onClose, onSubmit, validationLists, currentUserRole 
}) => {
    if (!isOpen) return null;

    const [truckNo, setTruckNo] = useState('');
    const [trailerNo, setTrailerNo] = useState('');
    const [type, setType] = useState('General');
    const [priority, setPriority] = useState('Normal');
    const [reason, setReason] = useState('');
    const [inspector, setInspector] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const newErrors: Record<string, string> = {};

        // --- STRICT VALIDATION LOGIC ---

        // 1. Validate Truck (Mandatory & Must Exist)
        const normalizedTruck = truckNo.trim().toUpperCase();
        const truckExists = validationLists.trucks.some(t => t.trim().toUpperCase() === normalizedTruck);
        if (!truckNo) {
            newErrors.truckNo = "Truck registration is required.";
        } else if (!truckExists) {
            newErrors.truckNo = "Vehicle not found in database. Contact Admin to add.";
        }

        // 2. Validate Trailer (Optional but Must Exist if entered)
        if (trailerNo) {
            const normalizedTrailer = trailerNo.trim().toUpperCase();
            const trailerExists = validationLists.trailers.some(t => t.trim().toUpperCase() === normalizedTrailer);
            if (!trailerExists) {
                newErrors.trailerNo = "Trailer not found in database.";
            }
        }

        // 3. Validate Inspector (Optional but Must Exist if entered)
        if (inspector) {
             const normalizedInspector = inspector.trim().toLowerCase();
             const inspectorExists = validationLists.inspectors.some(i => i.trim().toLowerCase() === normalizedInspector);
             if (!inspectorExists) {
                 newErrors.inspector = "Inspector not found. Please select from the list.";
             }
        }

        // 4. Reason Check
        if (!reason.trim()) newErrors.reason = "Please provide a reason or instruction.";

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            return;
        }

        setIsSubmitting(true);
        try {
            await onSubmit({ 
                truckNo: normalizedTruck, 
                trailerNo: trailerNo.trim().toUpperCase(), 
                type, 
                priority, 
                reason, 
                assignedInspector: inspector 
            });
            onClose();
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden transform transition-all scale-100 border border-slate-200">

                {/* Professional Header */}
                <div className="bg-indigo-600 px-6 py-4 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-indigo-500 rounded-lg flex items-center justify-center shadow-inner">
                            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path></svg>
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-white tracking-wide">Request Inspection</h3>
                            <p className="text-indigo-200 text-xs font-medium">Submit a vehicle for ad-hoc checking</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-indigo-200 hover:text-white p-1 rounded-full hover:bg-indigo-500 transition-colors">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>

                <div className="p-6">
                    <form onSubmit={handleSubmit} className="space-y-5">

                        <div className="p-3 bg-blue-50 rounded-lg border border-blue-100 flex items-start gap-3">
                            <svg className="w-5 h-5 text-blue-500 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                            <div className="text-xs text-blue-800 leading-relaxed">
                                <p className="font-bold mb-1">Restricted Selection</p>
                                <p>You can only select vehicles and inspectors that currently exist in the system. To add new assets, please contact the Administrator.</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <AutocompleteInput 
                                    label="Truck Reg No *" 
                                    value={truckNo}
                                    onChange={(v) => { setTruckNo(v); setErrors(prev => ({...prev, truckNo: ''})); }}
                                    options={validationLists.trucks}
                                    isRegNo={true}
                                    placeholder="Search..."
                                    error={!!errors.truckNo}
                                />
                                {errors.truckNo && <p className="text-[10px] text-red-600 font-bold mt-1 bg-red-50 p-1 rounded border border-red-100">{errors.truckNo}</p>}
                            </div>
                            <div>
                                <AutocompleteInput 
                                    label="Trailer Reg No" 
                                    value={trailerNo}
                                    onChange={(v) => { setTrailerNo(v); setErrors(prev => ({...prev, trailerNo: ''})); }}
                                    options={validationLists.trailers}
                                    isRegNo={true}
                                    placeholder="Optional"
                                    error={!!errors.trailerNo}
                                />
                                {errors.trailerNo && <p className="text-[10px] text-red-600 font-bold mt-1 bg-red-50 p-1 rounded border border-red-100">{errors.trailerNo}</p>}
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5 tracking-wide">Inspection Type</label>
                                <select 
                                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-medium"
                                    value={type}
                                    onChange={(e) => setType(e.target.value)}
                                >
                                    <option value="General">General</option>
                                    <option value="Petroleum">Petroleum V1</option>
                                    <option value="Petroleum_V2">Petroleum V2</option>
                                    <option value="Acid">Acid Tanker</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5 tracking-wide">Priority</label>
                                <select 
                                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-medium"
                                    value={priority}
                                    onChange={(e) => setPriority(e.target.value)}
                                >
                                    <option value="Normal">Normal</option>
                                    <option value="Urgent">Urgent (Dispatch Waiting)</option>
                                    <option value="Safety Concern">Safety Concern</option>
                                </select>
                            </div>
                        </div>

                        <div>
                            <AutocompleteInput 
                                label="Assign Inspector (Optional)" 
                                value={inspector}
                                onChange={(v) => { setInspector(v); setErrors(prev => ({...prev, inspector: ''})); }}
                                options={validationLists.inspectors}
                                isTitleCase={true}
                                placeholder="Select Inspector from list..."
                                error={!!errors.inspector}
                            />
                            {errors.inspector && <p className="text-[10px] text-red-600 font-bold mt-1 bg-red-50 p-1 rounded border border-red-100">{errors.inspector}</p>}
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5 tracking-wide">Reason / Instructions *</label>
                            <textarea 
                                className={`w-full p-3 bg-gray-50 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-medium h-24 placeholder-gray-400
                                    ${errors.reason ? 'border-red-300 ring-1 ring-red-200' : 'border-gray-200'}
                                `}
                                placeholder="e.g. Driver reported strange brake noise, please check."
                                value={reason}
                                onChange={(e) => { setReason(e.target.value); setErrors(prev => ({...prev, reason: ''})); }}
                                required
                            ></textarea>
                            {errors.reason && <p className="text-[10px] text-red-600 font-bold mt-1">{errors.reason}</p>}
                        </div>

                        <div className="pt-2 flex justify-end">
                            <button 
                                type="submit" 
                                disabled={isSubmitting}
                                className={`px-6 py-3 rounded-xl font-bold text-white shadow-lg transition-all flex items-center gap-2
                                    ${isSubmitting ? 'bg-indigo-400 cursor-wait' : 'bg-indigo-600 hover:bg-indigo-700 hover:scale-105 active:scale-95'}
                                `}
                            >
                                {isSubmitting ? (
                                    <>
                                        <svg className="animate-spin w-4 h-4 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                        Submitting...
                                    </>
                                ) : (
                                    'Submit Request'
                                )}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
};

