import React, { useState } from 'react';
import AutocompleteInput from './AutocompleteInput';
import { ValidationLists } from '../../types';

interface RequestInspectionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    validationLists: ValidationLists;
    currentUserRole: string;
}

const RequestInspectionModal: React.FC<RequestInspectionModalProps> = ({ 
    isOpen, onClose, onSubmit, validationLists, currentUserRole 
}) => {
    if (!isOpen) return null;

    const [truckNo, setTruckNo] = useState('');
    const [trailerNo, setTrailerNo] = useState('');
    const [type, setType] = useState('General');
    const [priority, setPriority] = useState('Normal');
    const [reason, setReason] = useState('');
    const [inspector, setInspector] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const newErrors: Record<string, string> = {};

        // --- STRICT VALIDATION LOGIC ---

        // 1. Validate Truck (Mandatory & Must Exist)
        const normalizedTruck = truckNo.trim().toUpperCase();
        // Check case-insensitive but store strict
        const truckExists = validationLists.trucks.some(t => t.trim().toUpperCase() === normalizedTruck);

        if (!truckNo) {
            newErrors.truckNo = "Truck registration is required.";
        } else if (!truckExists) {
            newErrors.truckNo = "Vehicle not found in database. Contact Admin.";
        }

        // 2. Validate Trailer (Optional but Must Exist if entered)
        if (trailerNo) {
            const normalizedTrailer = trailerNo.trim().toUpperCase();
            const trailerExists = validationLists.trailers.some(t => t.trim().toUpperCase() === normalizedTrailer);
            if (!trailerExists) {
                newErrors.trailerNo = "Trailer not found in database.";
            }
        }

        // 3. Validate Inspector (Optional but Must Exist if entered)
        if (inspector) {
             const normalizedInspector = inspector.trim().toLowerCase();
             const inspectorExists = validationLists.inspectors.some(i => i.trim().toLowerCase() === normalizedInspector);
             if (!inspectorExists) {
                 newErrors.inspector = "Inspector not found. Please select from the list.";
             }
        }

        // 4. Reason Check
        if (!reason.trim()) newErrors.reason = "Please provide a reason or instruction.";

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            return;
        }

        setIsSubmitting(true);
        try {
            await onSubmit({ 
                truckNo: normalizedTruck, 
                trailerNo: trailerNo.trim().toUpperCase(), 
                type, 
                priority, 
                reason,
                assignedInspector: inspector 
            });
            onClose();
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden transform transition-all scale-100 border border-slate-200">

