                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-white tracking-wide">Request Inspection</h3>
                            <p className="text-indigo-200 text-xs font-medium">Submit a vehicle for ad-hoc checking</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-indigo-200 hover:text-white p-1 rounded-full hover:bg-indigo-500 transition-colors">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
