            notifSheet.appendRow(["NOTIF-" + Date.now() + "-U", ticketOwnerEmail.toLowerCase().trim(), "info", "Ticket " + ticketId + " assigned to: " + body.assignedTo, new Date().toISOString(), "FALSE", "view:support"]);
