            notifSheet.appendRow(["NOTIF-" + Date.now(), recipient, "info", "New update on Ticket " + ticketId, new Date().toISOString(), "FALSE", "view:support"]);
        }
        return ResponseBuilder.success();
    }
    return ResponseBuilder.error("Ticket not found");
  }
};
