const PDFGenerator = {
  create: function(data) {
    if (data.title && (data.title.indexOf('General') > -1 || data.title.indexOf('GENERAL') > -1)) {
       return this.createGeneralReport(data);
    }
    return this.createGenericReport(data);
  },

  createGeneralReport: function(data) {
      // Helper to split items for 2 columns
      var items = data.items || [];
      var mid = Math.ceil(items.length / 2);
      var leftItems = items.slice(0, mid);
      var rightItems = items.slice(mid);

      var renderItemRow = function(item) {
          var status = item.status ? String(item.status).toUpperCase() : 'N/A';
          var color = '#000000';
          var fontWeight = 'normal';

          if (status === 'BAD' || status === 'FAIL') { 
              color = '#D32F2F'; // Red
              fontWeight = 'bold'; 
          }
          if (status === 'NEEDS ATTENTION') { 
              color = '#EF6C00'; // Orange
              fontWeight = 'bold'; 
          }
          if (status === 'GOOD') {
              color = '#000000'; // Black per checklist standard
          }

          return "<tr>" +
              "<td style='padding: 8px 4px; border-bottom: 1px solid #ccc; font-size: 11px; vertical-align: middle;'>" + item.label + "</td>" +
              "<td style='padding: 8px 4px; border-bottom: 1px solid #ccc; font-size: 11px; text-align: right; color: " + color + "; font-weight: " + fontWeight + "; vertical-align: middle; white-space: nowrap;'>" + status + "</td>" +
              "</tr>";
      };

      var renderTable = function(itemList) {
          var html = "<table style='width: 100%; border-collapse: collapse;'>";
          itemList.forEach(function(item) {
              html += renderItemRow(item);
          });
          html += "</table>";
          return html;
      };

      var dateStr = new Date(data.timestamp).toLocaleString('en-GB');

      return "<html><head><style>" +
          "body { font-family: Helvetica, Arial, sans-serif; padding: 20px; color: #333; margin: 0; }" +
          ".logo-container { text-align: center; margin-bottom: 10px; }" +
          ".header-table { width: 100%; border-collapse: collapse; border: 2px solid #000; margin-bottom: 15px; }" +
          ".header-table td { border: 1px solid #000; padding: 5px 10px; font-size: 12px; }" +
          ".title-row { background-color: #fff; text-align: center; font-weight: 900; font-size: 18px; text-transform: uppercase; padding: 10px; border-top: 2px solid #000; }" +

