          ".details-table td { padding: 10px; border-bottom: 1px solid #ccc; font-size: 12px; vertical-align: middle; }" +
          ".label { font-weight: 900; color: #444; text-transform: uppercase; margin-right: 5px; font-size: 11px; }" +
          ".val { font-weight: bold; color: #000; font-size: 13px; }" +
          ".col-border { border-right: 1px solid #ccc; }" +

          ".cols-wrapper { width: 100%; overflow: hidden; }" +
