interface OnboardingWizardProps {
    user: User;
    appScriptUrl: string;
    onComplete: (updatedUser: User) => void;
}

const OnboardingWizard: React.FC<OnboardingWizardProps> = ({ user, appScriptUrl, onComplete }) => {
    const [step, setStep] = useState(1); // 1: Password, 2: Email, 3: Success/Start Tour
    const [isLoading, setIsLoading] = useState(false);

    // Password State
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [pwdError, setPwdError] = useState('');

    // Email State
    const [emailCode, setEmailCode] = useState(''); // Simulated code
    const [isVerifyingEmail, setIsVerifyingEmail] = useState(false);

    const handlePasswordSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (newPassword.length < 4) { setPwdError("Minimum 4 characters required."); return; }
        if (newPassword !== confirmPassword) { setPwdError("Passwords do not match."); return; }

        setIsLoading(true);
        // We temporarily store password change in logic, actual sync happens at end or individually
        // For robustness, we update step by step.
        try {
            await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'update_user',
                    originalUsername: user.username,
                    password: newPassword,
                    preferences: { ...user.preferences, mustChangePassword: false }
                }),
                mode: 'no-cors'
            });
            // Advance
            setTimeout(() => {
                setStep(2);
                setIsLoading(false);
            }, 1500); // Fake delay for UX
        } catch (err) {
            setPwdError("Connection failed. Try again.");
            setIsLoading(false);
        }
    };

    const handleEmailActivate = async () => {
        setIsVerifyingEmail(true);
        // Simulate email activation process
        setTimeout(async () => {
            try {
                await fetch(appScriptUrl, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: 'update_user',
                        originalUsername: user.username,
                        preferences: { ...user.preferences, mustChangePassword: false, isEmailVerified: true }
                    }),
                    mode: 'no-cors'
                });
                setStep(3);
            } catch(e) {}
            setIsVerifyingEmail(false);
        }, 2000);
    };

    const handleFinish = () => {
        // Final update to local user state
        onComplete({
            ...user,
            preferences: { 
                ...user.preferences, 
                mustChangePassword: false, 
                isEmailVerified: true,
                hasCompletedTour: false // Will trigger tour next
            }
        });
    };

    return (
