            <div className="max-w-4xl w-full bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col md:flex-row h-[600px]">

                {/* Left Side: Visuals */}
                <div className="md:w-1/2 bg-gradient-to-br from-indigo-600 to-blue-800 p-10 flex flex-col justify-between text-white relative overflow-hidden">
