                            <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 ${step > 1 ? 'bg-green-400 border-green-400 text-indigo-900' : 'border-white text-white'} font-bold text-sm`}>
                                {step > 1 ? '✓' : '1'}
                            </div>
                            <span className="font-medium">Secure your account</span>
                        </div>
                        <div className={`w-0.5 h-6 bg-white/20 ml-4`}></div>
                        <div className={`flex items-center gap-4 transition-opacity duration-500 ${step >= 2 ? 'opacity-100' : 'opacity-50'}`}>
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 ${step > 2 ? 'bg-green-400 border-green-400 text-indigo-900' : 'border-white text-white'} font-bold text-sm`}>
