import React, { useState, useMemo } from 'react';
import { InspectionData } from '../types';
import SubscriptionLock from '../components/ui/SubscriptionLock';

interface AcidDashboardProps {
    stats: { total: number, passRate: number | string };
    startNewInspection: () => void;
    fetchHistory: () => void;
    isLoadingHistory: boolean;
    historyList: InspectionData[];
    onViewReport: (item: InspectionData) => void;
    onPrint: (item: InspectionData) => void;
    userRole?: string;
}

const AcidDashboard: React.FC<AcidDashboardProps> = ({ stats, startNewInspection, fetchHistory, isLoadingHistory, historyList, onViewReport, onPrint, userRole }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const displayList = useMemo(() => {
        let list = historyList;
        if (searchTerm.trim()) {
            const lowerSearch = searchTerm.toLowerCase();
            list = list.filter(item => 
                (item.truckNo && item.truckNo.toLowerCase().includes(lowerSearch)) ||
                (item.driverName && item.driverName.toLowerCase().includes(lowerSearch)) ||
                (item.inspectedBy && item.inspectedBy.toLowerCase().includes(lowerSearch))
            );
        } else {
            list = list.slice(0, 10);
        }
        return list;
    }, [historyList, searchTerm]);

    const getSummaryText = (item: InspectionData) => {
        const isPass = Number(item.rate) >= 4;
        const statusIcon = isPass ? '🟢' : Number(item.rate) === 3 ? '🟡' : '🔴';
        const statusText = isPass ? 'PASSED' : Number(item.rate) === 3 ? 'WARNING' : 'CRITICAL FAIL';

        return `ACID TANKER INSPECTION SUMMARY\n\n` +
               `Vehicle: ${item.truckNo}\n` +
               `Trailer: ${item.trailerNo || 'N/A'}\n` +
               `Date: ${new Date(item.timestamp).toLocaleDateString()} ${new Date(item.timestamp).toLocaleTimeString()}\n` +
               `Inspector: ${item.inspectedBy}\n\n` +
               `STATUS: ${statusIcon} ${statusText}\n` +
               `Safety Rating: ${item.rate}/5\n\n` +
               `Remarks:\n${item.remarks || 'None'}\n\n` +
               `Generated via SafetyCheck Pro`;
    };

    const handleShareReport = async (item: InspectionData) => {
        const shareData = {
            title: `Inspection Report: ${item.truckNo}`,
            text: getSummaryText(item)
        };

        try {
            if (navigator.share) {
                await navigator.share(shareData);
            } else {
                await navigator.clipboard.writeText(shareData.text);
                alert("Report summary copied to clipboard.");
            }
        } catch (err) {
            console.error('Error sharing:', err);
        }
    };

    const handleEmailReport = (item: InspectionData) => {
        const subject = `Acid Tanker Inspection Report: ${item.truckNo}`;
        const body = getSummaryText(item);
        window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`);
    };

    const isLocked = (window as any).isSubscriptionLocked || false;
    const canCreate = (userRole === 'Admin' || userRole === 'Inspector' || userRole === 'SuperAdmin') && !isLocked;

    return (
      <SubscriptionLock isLocked={isLocked}>
      <div className="max-w-6xl mx-auto space-y-8 animate-fadeIn">
          {/* Header Card - Professional Purple Theme */}
          <div className="bg-white rounded-2xl p-8 shadow-sm border border-purple-100 relative overflow-hidden group">
               <div className="absolute top-0 right-0 w-64 h-64 bg-purple-50 rounded-full blur-3xl transform translate-x-1/2 -translate-y-1/2 group-hover:bg-purple-100 transition-colors"></div>

               <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                   <div>
                       <div className="flex items-center gap-3 mb-2">
                           <div className="p-2 bg-purple-100 text-purple-700 rounded-lg">
                               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 2l-5.5 9h11z"/><path d="M10 13v6h4v-6z"/></svg>
                           </div>
                           <h2 className="text-2xl font-bold text-gray-800">Acid Tanker Inspection</h2>
                       </div>
                       <p className="text-gray-500 text-sm max-w-lg mb-6">Specialized safety checks for acid tankers, spill kits, and hazardous material compliance.</p>

                       <div className="flex flex-wrap gap-4">
                           {canCreate && (
                               <button 
                                 onClick={startNewInspection}
                                 className="px-6 py-3 bg-purple-600 hover:bg-purple-700 text-white font-bold rounded-xl shadow-lg shadow-purple-200 transition transform hover:scale-105 active:scale-95 flex items-center gap-2"
                               >
                                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"></path></svg>
