import React, { useState } from 'react';
import AutocompleteInput from './AutocompleteInput';
import { ValidationLists } from '../../types';

interface RequestInspectionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    validationLists: ValidationLists;
    currentUserRole: string;
}

const RequestInspectionModal: React.FC<RequestInspectionModalProps> = ({ 
    isOpen, onClose, onSubmit, validationLists, currentUserRole 
}) => {
    if (!isOpen) return null;

    const [truckNo, setTruckNo] = useState('');
    const [trailerNo, setTrailerNo] = useState('');
    const [type, setType] = useState('General');
    const [priority, setPriority] = useState('Normal');
    const [reason, setReason] = useState('');
    const [inspector, setInspector] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const newErrors: Record<string, string> = {};

        // --- STRICT VALIDATION LOGIC ---

        // 1. Validate Truck (Mandatory & Must Exist)
        const normalizedTruck = truckNo.trim().toUpperCase();
        // Check case-insensitive but store strict
        const truckExists = validationLists.trucks.some(t => t.trim().toUpperCase() === normalizedTruck);

        if (!truckNo) {
            newErrors.truckNo = "Truck registration is required.";
        } else if (!truckExists) {
            newErrors.truckNo = "Vehicle not found in database. Contact Admin.";
        }

        // 2. Validate Trailer (Optional but Must Exist if entered)
        if (trailerNo) {
            const normalizedTrailer = trailerNo.trim().toUpperCase();
            const trailerExists = validationLists.trailers.some(t => t.trim().toUpperCase() === normalizedTrailer);
            if (!trailerExists) {
                newErrors.trailerNo = "Trailer not found in database.";
            }
        }

        // 3. Validate Inspector (Optional but Must Exist if entered)
        if (inspector) {
             const normalizedInspector = inspector.trim().toLowerCase();
             const inspectorExists = validationLists.inspectors.some(i => i.trim().toLowerCase() === normalizedInspector);
             if (!inspectorExists) {
                 newErrors.inspector = "Inspector not found. Please select from the list.";
             }
        }

        // 4. Reason Check
        if (!reason.trim()) newErrors.reason = "Please provide a reason or instruction.";

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            return;
        }

        setIsSubmitting(true);
        try {
            await onSubmit({ 
                truckNo: normalizedTruck, 
                trailerNo: trailerNo.trim().toUpperCase(), 
                type, 
                priority, 
                reason,
                assignedInspector: inspector 
            });
            onClose();
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden transform transition-all scale-100 border border-slate-200">

                {/* Professional Header - Compact */}
                <div className="bg-indigo-600 px-5 py-3 flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-indigo-500 rounded-lg flex items-center justify-center shadow-inner text-white">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path></svg>
                        </div>
                        <div>
                            <h3 className="text-base font-bold text-white tracking-wide leading-tight">Request Inspection</h3>
                            <p className="text-indigo-200 text-[10px] font-medium leading-tight">Submit vehicle for ad-hoc check</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-indigo-200 hover:text-white p-1 rounded-full hover:bg-indigo-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>

                <div className="p-5">
                    <form onSubmit={handleSubmit} className="space-y-3">

                        <div className="p-2.5 bg-blue-50 rounded-lg border border-blue-100 flex items-start gap-2.5">
                            <svg className="w-4 h-4 text-blue-500 mt-0.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                            <div className="text-[10px] text-blue-800 leading-relaxed">
                                <p className="font-bold">Restricted Selection</p>
                                <p>Only existing vehicles/inspectors can be selected. Contact Admin to add new.</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <AutocompleteInput 
                                    label="Truck Reg No *" 
                                    value={truckNo}
                                    onChange={(v) => { setTruckNo(v); setErrors(prev => ({...prev, truckNo: ''})); }}
                                    options={validationLists.trucks}
                                    isRegNo={true}
                                    placeholder="Search..."
                                    error={!!errors.truckNo}
                                />
                                {errors.truckNo && <p className="text-[9px] text-red-600 font-bold mt-0.5 bg-red-50 p-0.5 rounded">{errors.truckNo}</p>}
                            </div>
                            <div>
                                <AutocompleteInput 
                                    label="Trailer Reg No" 
                                    value={trailerNo}
                                    onChange={(v) => { setTrailerNo(v); setErrors(prev => ({...prev, trailerNo: ''})); }}
                                    options={validationLists.trailers}
                                    isRegNo={true}
                                    placeholder="Optional"
                                    error={!!errors.trailerNo}
                                />
                                {errors.trailerNo && <p className="text-[9px] text-red-600 font-bold mt-0.5 bg-red-50 p-0.5 rounded">{errors.trailerNo}</p>}
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1 tracking-wide">Inspection Type</label>
                                <select 
                                    className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-xs font-medium"
                                    value={type}
                                    onChange={(e) => setType(e.target.value)}
                                >
                                    <option value="General">General</option>
                                    <option value="Petroleum">Petroleum V1</option>
                                    <option value="Petroleum_V2">Petroleum V2</option>
                                    <option value="Acid">Acid Tanker</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1 tracking-wide">Priority</label>
                                <select 
                                    className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-xs font-medium"
                                    value={priority}
                                    onChange={(e) => setPriority(e.target.value)}
                                >
                                    <option value="Normal">Normal</option>
                                    <option value="Urgent">Urgent (Dispatch Waiting)</option>
                                    <option value="Safety Concern">Safety Concern</option>
                                </select>
                            </div>
                        </div>

                        <div>
                            <AutocompleteInput 
                                label="Assign Inspector (Optional)" 
                                value={inspector}
                                onChange={(v) => { setInspector(v); setErrors(prev => ({...prev, inspector: ''})); }}
                                options={validationLists.inspectors}
                                isTitleCase={true}
                                placeholder="Select Inspector..."
                                error={!!errors.inspector}
                            />
                            {errors.inspector && <p className="text-[9px] text-red-600 font-bold mt-0.5 bg-red-50 p-0.5 rounded">{errors.inspector}</p>}
                        </div>

                        <div>
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1 tracking-wide">Reason / Instructions *</label>
                            <textarea 
                                className={`w-full p-2.5 bg-gray-50 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-xs font-medium h-20 placeholder-gray-400 resize-none
                                    ${errors.reason ? 'border-red-300 ring-1 ring-red-200' : 'border-gray-200'}
                                `}
