        remarks: formData.remarks,
        rate: formData.rate,
        items: reportItems,
        signatures: {
            inspector: formData.inspectorSignature,
            driver: formData.driverSignature
        },
        photos: {
            front: formData.photoFront,
            ls: formData.photoLS,
            rs: formData.photoRS,
            back: formData.photoBack,
            damage: formData.photoDamage
        },
        companyName: settings.companyName,
        companyLogo: settings.companyLogo
    };

    const rowData = targetHeaders.map(header => {
        if (header === 'id') return recordId;
        const val = (formData as any)[header];
        return (val === null || val === undefined) ? "" : val;
    });

    const payload = {
        sheet: targetSheet,
        action: "create",
        row: rowData,
        headers: targetHeaders,
        id: recordId,
        reportData: reportData,
        requestId: formData.requestId // Pass Request ID to close the loop
    };

    if (!navigator.onLine) {
        addToQueue(payload);
        clearDraft(activeModule);
        setSubmissionStatus('offline_saved');
        setTimeout(() => {
             startFreshInspection(activeModule); 
             setViewMode('dashboard');
             setSubmissionStatus('idle');
             showToast("Offline Mode: Report Saved. Will sync when online.", 'info');
        }, 2000);
        return;
    }

    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 15000);

        await fetch(appScriptUrl, {
            method: 'POST',
            body: JSON.stringify(payload),
            mode: 'no-cors', 
            headers: { 'Content-Type': 'text/plain' },
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        clearDraft(activeModule);
        setSubmissionStatus('success');

        setTimeout(() => {
             startFreshInspection(activeModule); 
             setViewMode('dashboard');
             setSubmissionStatus('idle');
             fetchHistory(true); 
             fetchNotifications();
             showToast(formData.requestId ? "Request Fulfilled & Report Submitted!" : "Inspection Submitted & Email Sent!", 'success');
        }, 2500);

    } catch (error: any) {
        console.error("Submission Error", error);
        addToQueue(payload);
        clearDraft(activeModule); 
        setSubmissionStatus('offline_saved');
        const isTimeout = error.name === 'AbortError';
        const msg = isTimeout ? "Slow Network detected. Saved to offline queue." : "Network Error. Report queued for auto-sync.";
        setTimeout(() => {
             startFreshInspection(activeModule); 
             setViewMode('dashboard');
             setSubmissionStatus('idle');
             showToast(msg, 'warning');
        }, 2500);
    }
  };

  const handlePrint = () => window.print();
  const handleQuickPrint = (item: InspectionData) => {
      setSelectedReportData(item);
      setTimeout(() => window.print(), 500);
  };
  const handleViewReport = (item: InspectionData | null) => {
    setSelectedReportData(item);
    setIsReportModalOpen(true);
  };

  const handleNotificationAction = (id: string, onNavigate?: (module: string) => void) => {
      handleMarkNotificationRead(id, (module) => {
          // Special handling for request inspection start links
          // Link format: request:start_inspection|type|truck|trailer|requester|reason|reqId
          const targetNotification = notifications.find(n => n.id === id);
          if (targetNotification?.actionLink?.startsWith('request:start_inspection')) {
              const parts = targetNotification.actionLink.split('|');
              const type = parts[1].toLowerCase();
              const truck = parts[2];
              const trailer = parts[3];
              const requester = parts[4];
              const reason = parts[5];
              const reqId = parts[6] || ''; // Extract Request ID

              let targetMod = 'general';
              if (type.includes('petroleum_v2')) targetMod = 'petroleum_v2';
              else if (type.includes('petroleum')) targetMod = 'petroleum';
              else if (type.includes('acid')) targetMod = 'acid';

              setActiveModule(targetMod);

              startFreshInspection(targetMod, {
                  truckNo: truck,
                  trailerNo: trailer,
                  remarks: `** AD-HOC REQUEST **\nInitiated by: ${requester}\nReason: ${reason}`,
                  requestId: reqId // Attach ID for loop closure
              });

              showToast("Starting requested inspection...", 'info');
          } else {
              if (onNavigate) onNavigate(module);
              else {
                  setActiveModule(module);
                  setViewMode('dashboard');
              }
          }
      });
  };

  if (!currentUser) {
      return (
          <LoginView 
            onLogin={handleLogin} 
            appScriptUrl={appScriptUrl}
            setAppScriptUrl={setAppScriptUrl}
            settings={settings}
          />
      );
  }

  if (showOnboarding && currentUser) {
      return (
          <OnboardingWizard 
              user={currentUser} 
              appScriptUrl={appScriptUrl} 
              onComplete={handleOnboardingComplete} 
          />
      );
  }

  const canAcknowledge = ['Admin', 'Maintenance', 'Inspector', 'SuperAdmin'].includes(currentUser.role || '');
  const isSuperAdmin = currentUser.role === 'SuperAdmin';
  const showMaintenanceOverlay = settings.maintenanceMode && !isSuperAdmin;

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 relative">
      <SubmissionOverlay status={submissionStatus} />
      {showTour && <SystemTour onComplete={handleTourComplete} />}
      <MaintenanceOverlay isActive={showMaintenanceOverlay} message={settings.maintenanceMessage || ''} onLogout={handleLogout} />
      <NetworkStatus queueLength={offlineQueue.length} isSyncing={isSyncing} isPoorConnection={isPoorConnection} onRetry={syncOfflineQueue} />
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <RequestInspectionModal
          isOpen={isRequestModalOpen}
          onClose={() => setIsRequestModalOpen(false)}
          onSubmit={handleRequestInspectionSubmit}
          validationLists={validationLists}
          currentUserRole={currentUser.role || ''}
      />

      <InspectionStartModal 
          isOpen={isStartModalOpen}
          onClose={() => setIsStartModalOpen(false)}
          moduleName={targetModuleForStart || 'General'}
          hasDraft={!!targetModuleForStart && hasDraft(targetModuleForStart)}
          onStartNew={() => {
              if (targetModuleForStart) startFreshInspection(targetModuleForStart);
              setIsStartModalOpen(false);
          }}
          onResume={() => {
              if (targetModuleForStart) resumeDraftInspection(targetModuleForStart);
              setIsStartModalOpen(false);
          }}
      />

      {upgradeFeature && <UpgradeModal featureName={upgradeFeature} onClose={() => setUpgradeFeature(null)} />}

      {isProfileModalOpen && currentUser && (
          <ProfileModal 
              user={currentUser}
              appScriptUrl={appScriptUrl}
              onClose={() => setIsProfileModalOpen(false)}
              showToast={showToast}
              onUpdateSuccess={(updatedUser) => {
                   setCurrentUser(updatedUser);
                   localStorage.setItem('safetyCheck_user', JSON.stringify(updatedUser));
              }}
          />
      )}

      {isReportModalOpen && (
          <ReportViewerModal 
            onClose={() => setIsReportModalOpen(false)} 
            onPrint={handlePrint}
            title="Inspection Report"
          >
               <div className="print-only-container">
                    {activeModule === 'petroleum' ? (
                        <PrintablePetroleumReport data={selectedReportData || formInitialData} settings={settings} />
                    ) : activeModule === 'petroleum_v2' ? (
                        <PrintablePetroleumV2Report data={selectedReportData || formInitialData} settings={settings} />
                    ) : activeModule === 'acid' ? (
                        <PrintableAcidReport data={selectedReportData || formInitialData} settings={settings} />
                    ) : (
                        <PrintableGeneralReport data={selectedReportData || formInitialData} settings={settings} />
                    )}
               </div>
          </ReportViewerModal>
      )}

      <div className="print-only hidden p-0 bg-white">
         {activeModule === 'petroleum' ? (
             <PrintablePetroleumReport data={selectedReportData || formInitialData} settings={settings} />
         ) : activeModule === 'petroleum_v2' ? (
             <PrintablePetroleumV2Report data={selectedReportData || formInitialData} settings={settings} />
         ) : activeModule === 'acid' ? (
             <PrintableAcidReport data={selectedReportData || formInitialData} settings={settings} />
         ) : (
             <PrintableGeneralReport data={selectedReportData || formInitialData} settings={settings} />
         )}
      </div>

      <div className="relative z-10 bg-gray-50 min-h-screen">
          <Sidebar 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
            activeModule={activeModule}
            onSelectModule={(m) => {
                setActiveModule(m);
                setViewMode('dashboard');
            }}
            onLockedItemClick={(feature) => setUpgradeFeature(feature)}
            settings={settings}
            user={currentUser}
            onLogout={handleLogout}
            onEditProfile={() => setIsProfileModalOpen(true)}
            subscription={subscription} 
            onRequestInspection={() => {
                fetchHistory(false);
                setIsRequestModalOpen(true);
            }} 
          />

          <div className="lg:pl-64 min-h-screen flex flex-col transition-all duration-300">
            <SubscriptionAlert 
                subscription={subscription} 
                user={currentUser} 
                onManage={() => { setActiveModule('settings'); setViewMode('dashboard'); }}
            />

            <header className="bg-emerald-950 border-b border-emerald-900 sticky top-0 z-40 shadow-sm">
              <div className="px-4 py-3 flex justify-between items-center text-white">
                <div className="flex items-center gap-3">
                    <button id="sidebar-toggle" onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1 hover:bg-slate-800 rounded">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"></path></svg>
                    </button>
                    <div className="flex flex-col">
                        <h1 className="text-lg md:text-xl font-bold flex items-center gap-2">
                            {activeModule === 'overview' ? 'Executive Dashboard' : 
                            activeModule === 'petroleum' ? 'Petroleum V1' : 
                            activeModule === 'petroleum_v2' ? 'Petroleum V2' : 
                            activeModule === 'acid' ? 'Acid' : 
                            activeModule === 'settings' ? 'System' :
                            activeModule === 'users' ? 'Users' :
                            activeModule === 'support' ? 'Support Hub' :
                            activeModule === 'maintenance' ? 'Superadmin Console' :
                            'SafetyCheck'}
                        </h1>
                        {isBackgroundFetching && (
                            <div className="flex items-center gap-1.5 text-[10px] text-emerald-300 animate-pulse">
                                Checking for updates...
                            </div>
                        )}
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {offlineQueue.length > 0 && (
                        <button
                            id="sync-status-btn"
                            onClick={syncOfflineQueue}
                            disabled={isSyncing} 
                            className={`hidden md:flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold transition-all shadow-sm
                                ${isSyncing 
                                    ? 'bg-blue-600 text-white cursor-wait' 
                                    : isPoorConnection 
                                        ? 'bg-red-500 text-white hover:bg-red-600 animate-pulse' 
                                        : 'bg-amber-500 text-white hover:bg-amber-600'}
                            `}
                        >
                            {isSyncing ? (
                                <>
                                    <svg className="animate-spin w-3 h-3" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                    <span>Syncing...</span>
                                </>
                            ) : (
                                <span>{isPoorConnection ? 'Retry Upload' : `Pending (${offlineQueue.length})`}</span>
                            )}
                        </button>
                    )}

                    <div id="notification-bell">
                        <NotificationCenter 
                            notifications={notifications}
                            onMarkAsRead={(id) => handleNotificationAction(id, (m) => { setActiveModule(m); setViewMode('dashboard'); })}
                            onDismiss={handleDismissNotification}
                            onClearAll={handleClearAllNotifications}
                            onAcknowledge={handleGlobalAcknowledge}
                            canAcknowledge={canAcknowledge}
                        />
                    </div>
                </div>
              </div>
            </header>

            {viewMode === 'form' ? (
                <InspectionFormView 
                    initialData={formInitialData}
                    activeModule={activeModule}
                    validationLists={validationLists}
                    settings={settings}
                    onSaveDraft={handleExitForm} 
                    onExit={() => handleExitForm()} 
                    onSubmit={handleGoogleSheetSubmit}
                    submissionStatus={submissionStatus}
                    onViewReport={handleViewReport}
                />
            ) : (
                <main className="flex-1 p-4 md:p-6 lg:p-8 max-w-6xl mx-auto w-full">
                  {activeModule === 'overview' && (
                      <OverviewDashboard 
                          appScriptUrl={appScriptUrl}
                          onNavigate={(module) => { setActiveModule(module); setViewMode('dashboard'); }}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'settings' && (
                      <SettingsView 
                          settings={settings}
                          setSettings={setSettings}
                          appScriptUrl={appScriptUrl}
                          setAppScriptUrl={setAppScriptUrl}
                          handleSaveSettings={handleSaveSettings}
                          isSavingSettings={isSavingSettings}
                          showToast={showToast}
                          user={currentUser} 
                      />
                  )}

                  {activeModule === 'users' && (
                      <UserManagementView 
                          currentUser={currentUser}
                          appScriptUrl={appScriptUrl}
                          showToast={showToast}
                          validationLists={validationLists}
                          settings={settings}
                      />
                  )}

                  {activeModule === 'support' && (
                      <SupportView 
                          appScriptUrl={appScriptUrl}
                          currentUser={currentUser}
                          showToast={showToast}
                          settings={settings}
                          validationLists={validationLists}
                      />
                  )}

                  {activeModule === 'maintenance' && isSuperAdmin && (
                      <MaintenanceView 
                          user={currentUser}
                          appScriptUrl={appScriptUrl}
                          settings={settings}
                          onSettingsUpdate={(newS) => setSettings(p => ({...p, ...newS}))}
                          showToast={showToast}
                      />
                  )}

                  {activeModule === 'general' && (
                      <GeneralDashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('general')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'petroleum' && (
                      <PetroleumDashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('petroleum')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'petroleum_v2' && (
                      <PetroleumV2Dashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('petroleum_v2')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}

                  {activeModule === 'acid' && (
                      <AcidDashboard 
                          stats={stats}
                          startNewInspection={() => handleInitiateStartInspection('acid')}
                          fetchHistory={() => fetchHistory(true)}
                          isLoadingHistory={isLoadingHistory}
                          historyList={historyList}
                          onViewReport={handleViewReport}
                          onPrint={handleQuickPrint}
                          userRole={currentUser?.role}
                      />
                  )}
                </main>
            )}
          </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { InspectionData, InspectionStatus, InspectionItemConfig, ValidationLists, SystemSettings } from '../types';
import { INSPECTION_ITEMS, INSPECTION_CATEGORIES, PETROLEUM_INSPECTION_ITEMS, PETROLEUM_CATEGORIES, ACID_INSPECTION_ITEMS, ACID_CATEGORIES, PETROLEUM_V2_ITEMS, PETROLEUM_V2_CATEGORIES, SECTIONS } from '../constants';
import CameraCapture from '../components/CameraCapture';
import SignaturePad from '../components/SignaturePad';
import StatusButton from '../components/ui/StatusButton';
import Input from '../components/ui/Input';
import AutocompleteInput from '../components/ui/AutocompleteInput';
import PrintableGeneralReport from '../components/reports/PrintableGeneralReport';
import PrintablePetroleumReport from '../components/reports/PrintablePetroleumReport';
import PrintablePetroleumV2Report from '../components/reports/PrintablePetroleumV2Report';
import PrintableAcidReport from '../components/reports/PrintableAcidReport';

interface InspectionFormViewProps {
    initialData: InspectionData;
    activeModule: string;
    validationLists: ValidationLists;
    settings: SystemSettings;
    onSaveDraft: (data: InspectionData) => void;
    onSubmit: (data: InspectionData) => void;
    onExit: () => void;
    submissionStatus: 'idle' | 'submitting' | 'success' | 'offline_saved';
    onViewReport: (data: InspectionData) => void;
}

const InspectionFormView: React.FC<InspectionFormViewProps> = ({ 
    initialData, activeModule, validationLists, settings, onSaveDraft, onSubmit, onExit, submissionStatus, onViewReport 
}) => {
    const [formData, setFormData] = useState<InspectionData & any>(initialData);
    const [currentSection, setCurrentSection] = useState(0);
    const [errors, setErrors] = useState<Record<string, boolean>>({});

    const updateField = (field: string, value: any) => {
        setFormData((prev: any) => ({ ...prev, [field]: value }));
        if (errors[field]) {
            setErrors(prev => {
                const next = {...prev};
                delete next[field];
                return next;
            });
        }
    };

    const getItemsForStep = (stepIndex: number): InspectionItemConfig[] => {
        let categories: string[] = [];
        let sourceItems: InspectionItemConfig[] = [];

        if (activeModule === 'general') sourceItems = INSPECTION_ITEMS;
        else if (activeModule === 'petroleum') sourceItems = PETROLEUM_INSPECTION_ITEMS;
        else if (activeModule === 'petroleum_v2') sourceItems = PETROLEUM_V2_ITEMS;
        else if (activeModule === 'acid') sourceItems = ACID_INSPECTION_ITEMS;

        if (activeModule === 'general') {
            if (stepIndex === 2) categories = [INSPECTION_CATEGORIES.PPE, INSPECTION_CATEGORIES.DOCUMENTATION];
            if (stepIndex === 3) categories = [INSPECTION_CATEGORIES.VEHICLE_EXTERIOR, INSPECTION_CATEGORIES.LIGHTS_ELECTRICAL];
            if (stepIndex === 4) categories = [INSPECTION_CATEGORIES.MECHANICAL, INSPECTION_CATEGORIES.TRAILER];
        } else if (activeModule === 'petroleum') {
            if (stepIndex === 2) categories = [PETROLEUM_CATEGORIES.TRUCK_EQUIPMENT];
            if (stepIndex === 3) categories = [PETROLEUM_CATEGORIES.TYRES, PETROLEUM_CATEGORIES.PPE_ID];
            if (stepIndex === 4) categories = [PETROLEUM_CATEGORIES.DOCUMENTS, PETROLEUM_CATEGORIES.ONBOARD];
        } else if (activeModule === 'petroleum_v2') {
            if (stepIndex === 2) categories = [PETROLEUM_V2_CATEGORIES.PRIME_MOVER];
            if (stepIndex === 3) categories = [PETROLEUM_V2_CATEGORIES.TRAILER_TANKS];
            if (stepIndex === 4) categories = [PETROLEUM_V2_CATEGORIES.DRIVER, PETROLEUM_V2_CATEGORIES.SAFETY_SIGNS, PETROLEUM_V2_CATEGORIES.DOCUMENTS];
        } else if (activeModule === 'acid') {
            if (stepIndex === 2) categories = [ACID_CATEGORIES.PPE];
            if (stepIndex === 3) categories = [ACID_CATEGORIES.VEHICLE];
            if (stepIndex === 4) categories = [ACID_CATEGORIES.SPILL_KIT, ACID_CATEGORIES.DOCUMENTATION];
        }

        return sourceItems.filter(item => categories.includes(item.category));
    };

    const validateSection = (sectionIndex: number): boolean => {
        const newErrors: Record<string, boolean> = {};

        if (sectionIndex === 0) {
            if (!formData.truckNo) newErrors.truckNo = true;
            if (!formData.trailerNo) newErrors.trailerNo = true;
            if (!formData.driverName) newErrors.driverName = true;
            if (!formData.location) newErrors.location = true;
            if (!formData.odometer) newErrors.odometer = true;
            if (activeModule !== 'general' && !formData.jobCard) newErrors.jobCard = true;
        }

        if (sectionIndex >= 2 && sectionIndex <= 4) {
            const requiredItems = getItemsForStep(sectionIndex);

            requiredItems.forEach(item => {
                const val = formData[item.id];
                if (!val) {
                    newErrors[item.id] = true;
                }
            });
        }

        if (sectionIndex === 5) {
             if (!formData.remarks || formData.remarks.trim() === '') newErrors.remarks = true;
             if (!formData.rate || formData.rate === 0) newErrors.rate = true;
             if (!formData.inspectorSignature) newErrors.inspectorSignature = true;
             if (!formData.driverSignature) newErrors.driverSignature = true;
        }

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            window.scrollTo({ top: 0, behavior: 'smooth' }); 
            return false;
        }

        setErrors({});
        return true;
    };

    const validateFullForm = (): boolean => {
        for (let i = 0; i <= 5; i++) {
            if (!validateSection(i)) {
                setCurrentSection(i); 
                return false;
            }
        }
        return true;
    };

    const handleNext = () => {
        if (!validateSection(currentSection)) return;
        window.scrollTo({ top: 0, behavior: 'smooth' });
        setCurrentSection(prev => Math.min(prev + 1, SECTIONS.length - 1));
    };

    const handleBack = () => {
        if (currentSection === 0) {
            onExit();
        } else {
            window.scrollTo({ top: 0, behavior: 'smooth' });
            setCurrentSection(prev => Math.max(prev - 1, 0));
        }
    };

    const handleSubmitInspection = () => {
        if (validateFullForm()) {
            onSubmit(formData);
        }
    };

    const renderDetailsSection = () => (
      <div className="space-y-6 animate-fadeIn">
        {formData.requestId && (
            <div className="bg-gradient-to-r from-indigo-500 to-blue-600 p-4 rounded-xl shadow-lg flex items-center justify-between text-white border border-indigo-400">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-white/20 rounded-lg backdrop-blur-sm">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path></svg>
                    </div>
                    <div>
                        <p className="text-xs font-bold uppercase tracking-widest text-indigo-100">Task Assignment</p>
                        <p className="text-sm font-bold">Fulfilling Request #{formData.requestId}</p>
                    </div>
                </div>
                <span className="text-[10px] bg-white text-indigo-600 px-2 py-1 rounded font-bold shadow-sm uppercase tracking-wide">
                    Priority Action
                </span>
            </div>
        )}

        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
            <span className="bg-blue-100 text-blue-700 p-2 rounded-lg">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V8a2 2 0 00-2-2h-5m-4 0V5a2 2 0 114 0v1m-4 0c0 .667.333 1 1 1v1m2-2c-.667 0-1 .333-1 1v1"></path></svg>
            </span>
            Vehicle & Driver Information
          </h2>
          <div className="text-xs text-red-500 font-medium mb-4">* All fields in this section are required.</div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <AutocompleteInput 
              label="Truck/Vehicle Reg No. *" 
              value={formData.truckNo} 
              onChange={v => updateField('truckNo', v)} 
              options={validationLists.trucks}
              placeholder="e.g. AHB 1502 ZM"
              isRegNo={true}
              error={errors.truckNo}
            />
            <AutocompleteInput 
              label="Trailer/Unit Reg No. *" 
              value={formData.trailerNo} 
              onChange={v => updateField('trailerNo', v)} 
              options={validationLists.trailers}
              placeholder="e.g. AHB 1502 ZM"
              isRegNo={true}
              error={errors.trailerNo}
            />

            <Input 
              label="Job Card #" 
              value={formData.jobCard || ''} 
              onChange={v => updateField('jobCard', v)} 
              error={errors.jobCard}
            />

            <AutocompleteInput 
