                    {icon}
                </span>

                <div className="flex flex-col items-start relative z-10 text-left flex-1 min-w-0">
                    <div className="flex items-center justify-between w-full">
                        <span className={`text-sm font-semibold tracking-wide truncate leading-tight ${isActive ? 'text-white' : isLocked ? 'text-slate-600' : isDanger ? 'text-red-400 group-hover:text-red-200' : 'text-slate-300 group-hover:text-white'}`}>
