import { useState, useEffect, useRef } from 'react';
import { SystemSettings } from '../types';
import { PRE_CONFIGURED_SCRIPT_URL } from '../constants';

export const useSettings = () => {
    const [appScriptUrl, setAppScriptUrl] = useState<string>(() => {
        if (PRE_CONFIGURED_SCRIPT_URL && PRE_CONFIGURED_SCRIPT_URL.length > 0) return PRE_CONFIGURED_SCRIPT_URL;
        if (typeof window !== 'undefined') return localStorage.getItem('safetyCheck_scriptUrl') || '';
        return '';
    });

    const [settings, setSettings] = useState<SystemSettings>(() => {
        if (typeof window !== 'undefined') {
            const saved = localStorage.getItem('safetyCheck_settings');
            if (saved) {
                try { return JSON.parse(saved); } catch (e) { console.error("Failed to parse local settings", e); }
            }
        }
        return { companyName: 'My Transport Co.', managerEmail: '' };
    });

    const [isSavingSettings, setIsSavingSettings] = useState(false);
    // Ref to track if we are already fetching to prevent overlap
    const isFetchingRef = useRef(false);

    useEffect(() => {
        if (appScriptUrl) {
            // Initial fetch
            fetchSystemSettings(appScriptUrl);

            // Poll every 30 seconds to check for Lockdown/Maintenance mode updates
            const intervalId = setInterval(() => {
                fetchSystemSettings(appScriptUrl);
            }, 30000);

            return () => clearInterval(intervalId);
        }
    }, [appScriptUrl]);

    const fetchSystemSettings = async (url: string) => {
        if (!url || typeof url !== 'string' || !url.startsWith('http')) return;
        if (!navigator.onLine || isFetchingRef.current) return;

        isFetchingRef.current = true;
        try {
            const response = await fetch(`${url}?t=${new Date().getTime()}`);
            if (!response.ok) {
                return;
            }

            const json = await response.json();
            const settingsRows = json['System_Settings'];

            if (settingsRows && Array.isArray(settingsRows) && settingsRows.length > 1) {
                const latestConfig = settingsRows[settingsRows.length - 1];
                if (latestConfig && latestConfig.length >= 2) {
                    const maintenanceModeVal = String(latestConfig[7]).toUpperCase().trim();

                    const remoteSettings: SystemSettings = {
                        companyName: latestConfig[0] || 'My Transport Co.',
                        managerEmail: latestConfig[1] || '',
                        companyLogo: (latestConfig[4] && String(latestConfig[4]).length > 100) ? latestConfig[4] : undefined,
                        mobileApkLink: latestConfig[5] || '', 
                        webAppUrl: latestConfig[6] || '',
                        maintenanceMode: maintenanceModeVal === 'TRUE',
                        maintenanceMessage: latestConfig[8] || ''
                    };

                    // Only update state if something changed to prevent re-renders
                    setSettings(prev => {
                        if (JSON.stringify(prev) !== JSON.stringify(remoteSettings)) {
                            try {
                                localStorage.setItem('safetyCheck_settings', JSON.stringify(remoteSettings));
                            } catch (e) { /* Storage quota exceeded */ }
                            return { ...prev, ...remoteSettings };
                        }
                        return prev;
                    });
                }
            }
        } catch (error) {
            // Silently fail on network error
        } finally {
            isFetchingRef.current = false;
        }
    };

    const handleSaveSettings = async () => {
        setIsSavingSettings(true);
        try {
            // Local Save
            localStorage.setItem('safetyCheck_settings', JSON.stringify(settings));
            localStorage.setItem('safetyCheck_scriptUrl', appScriptUrl);

            // Server Sync
            if (appScriptUrl && appScriptUrl.startsWith('http') && navigator.onLine) {
                 await fetch(appScriptUrl, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: 'update_settings',
                        companyName: settings.companyName,
                        managerEmail: settings.managerEmail,
                        companyLogo: settings.companyLogo,
                        mobileApkLink: settings.mobileApkLink,
                        webAppUrl: settings.webAppUrl,
                        maintenanceMode: settings.maintenanceMode,
                        maintenanceMessage: settings.maintenanceMessage
                    })
                });
            }
        } catch (error) {
            console.error("Save Settings Failed", error);
        } finally {
            setTimeout(() => {
                setIsSavingSettings(false);
            }, 800);
        }
    };

    return { 
        settings, 
        setSettings, 
        appScriptUrl, 
        setAppScriptUrl, 
        isSavingSettings, 
        setIsSavingSettings, 
        fetchSystemSettings,
        handleSaveSettings
    };
};

import React, { useState } from 'react';
import { User, SystemSettings } from '../types';

interface MaintenanceViewProps {
    user: User;
    appScriptUrl: string;
    settings: SystemSettings;
    onSettingsUpdate: (newSettings: Partial<SystemSettings>) => void;
    showToast: (msg: string, type: 'success' | 'error' | 'info') => void;
}

const MaintenanceView: React.FC<MaintenanceViewProps> = ({ user, appScriptUrl, settings, onSettingsUpdate, showToast }) => {
    const [msgType, setMsgType] = useState<'info' | 'warning' | 'critical'>('info');
    const [msgBody, setMsgBody] = useState('');
    const [isSending, setIsSending] = useState(false);

    // Maintenance Mode State
    const [maintMode, setMaintMode] = useState(settings.maintenanceMode || false);
    const [maintMessage, setMaintMessage] = useState(settings.maintenanceMessage || 'System under scheduled maintenance.');
    const [isSavingMaint, setIsSavingMaint] = useState(false);

    const handleBroadcast = async () => {
        if (!msgBody.trim()) {
            showToast("Please enter a message.", "error");
            return;
        }
        setIsSending(true);
        try {
            await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'broadcast',
                    type: msgType,
                    message: msgBody
                }),
                mode: 'no-cors'
            });
            showToast("Broadcast sent successfully!", "success");
            setMsgBody('');
        } catch (e) {
            showToast("Failed to send broadcast.", "error");
        } finally {
            setIsSending(false);
        }
    };

    const handleSaveMaintenance = async () => {
        setIsSavingMaint(true);
        try {
            // 1. Update Database
            // Re-use update_settings but only for maintenance fields
            await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'update_settings',
                    companyName: settings.companyName,
                    managerEmail: settings.managerEmail,
                    companyLogo: settings.companyLogo,
                    mobileApkLink: settings.mobileApkLink,
                    webAppUrl: settings.webAppUrl,
                    maintenanceMode: maintMode,
                    maintenanceMessage: maintMessage
                })
            });

            // 2. Update React State (App level)
            const newSettings = { maintenanceMode: maintMode, maintenanceMessage: maintMessage };
            onSettingsUpdate(newSettings);

            // 3. FORCE Local Storage Update (Fixes persistence on refresh)
            const currentStored = localStorage.getItem('safetyCheck_settings');
            if (currentStored) {
                const parsed = JSON.parse(currentStored);
                const updated = { ...parsed, ...newSettings };
                localStorage.setItem('safetyCheck_settings', JSON.stringify(updated));
            }

            showToast(maintMode ? "System Lockdown ACTIVATED" : "System Status Normal", "success");
        } catch (e) {
            showToast("Failed to update system status.", "error");
        } finally {
            setIsSavingMaint(false);
        }
    };

    const applyTemplate = (type: 'upgrade' | 'downtime' | 'restart') => {
        if (type === 'upgrade') {
            setMsgType('info');
            setMsgBody('System Upgrade scheduled for tonight at 22:00. Brief downtime expected.');
        } else if (type === 'downtime') {
            setMsgType('critical');
            setMsgBody('Emergency Maintenance: System will be offline in 15 minutes. Please save your work.');
        } else if (type === 'restart') {
            setMsgType('warning');
            setMsgBody('Server restart initiated. Performance may be degraded for 5 minutes.');
        }
    };

    return (
        <div className="max-w-5xl mx-auto animate-fadeIn pb-12 space-y-8">
            <div className="flex items-center gap-4 mb-6">
                <div className="p-3 bg-red-600 rounded-xl shadow-lg text-white">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                </div>
                <div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">Superadmin Console</h1>
                    <p className="text-slate-500 font-medium">System Control & Emergency Broadcasts</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* LEFT: Broadcast Center */}
                <div className="space-y-6">
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z"></path></svg>
                                Broadcast Alert
                            </h3>
                            <span className="text-[10px] font-bold bg-blue-100 text-blue-700 px-2 py-1 rounded uppercase">All Users</span>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Message Content</label>
                                <textarea 
                                    className="w-full p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none min-h-[120px] text-sm text-slate-700 bg-slate-50 font-medium placeholder-slate-400"
                                    placeholder="Type your alert message here..."
                                    value={msgBody}
                                    onChange={e => setMsgBody(e.target.value)}
                                ></textarea>
                            </div>

                            <div className="flex gap-4">
                                <div className="flex-1">
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Severity</label>
