    settings: SystemSettings;
    onSettingsUpdate: (newSettings: Partial<SystemSettings>) => void;
    showToast: (msg: string, type: 'success' | 'error' | 'info') => void;
}

const MaintenanceView: React.FC<MaintenanceViewProps> = ({ user, appScriptUrl, settings, onSettingsUpdate, showToast }) => {
    const [msgType, setMsgType] = useState<'info' | 'warning' | 'critical'>('info');
    const [msgBody, setMsgBody] = useState('');
    const [isSending, setIsSending] = useState(false);

    // Internal state for the switch to feel fast
    const [maintMode, setMaintMode] = useState(settings.maintenanceMode || false);
    const [maintMessage, setMaintMessage] = useState(settings.maintenanceMessage || 'System under scheduled maintenance.');
    const [isSavingMaint, setIsSavingMaint] = useState(false);

    // Sync internal state if settings change from re-fetch
    useEffect(() => {
        setMaintMode(settings.maintenanceMode || false);
        setMaintMessage(settings.maintenanceMessage || 'System under scheduled maintenance.');
    }, [settings.maintenanceMode, settings.maintenanceMessage]);

    const handleBroadcast = async () => {
        if (!msgBody.trim()) {
            showToast("Please enter a message.", "error");
            return;
        }
        setIsSending(true);
        try {
            await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'broadcast',
                    type: msgType,
                    message: msgBody
                }),
                mode: 'no-cors'
            });
            showToast("Broadcast sent successfully!", "success");
            setMsgBody('');
        } catch (e) {
            showToast("Failed to send broadcast.", "error");
        } finally {
            setIsSending(false);
        }
    };

    const handleSaveMaintenance = async () => {
        setIsSavingMaint(true);
        try {
            // 1. Update Database
            await fetch(appScriptUrl, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'update_settings',
                    companyName: settings.companyName,
                    managerEmail: settings.managerEmail,
                    companyLogo: settings.companyLogo,
                    mobileApkLink: settings.mobileApkLink,
                    webAppUrl: settings.webAppUrl,
                    maintenanceMode: maintMode,
                    maintenanceMessage: maintMessage
                })
            });

            // 2. IMPORTANT: Update parent state AND local storage immediately
            // This prevents the refresh revert issue
            const updatedSettings = { ...settings, maintenanceMode: maintMode, maintenanceMessage: maintMessage };
            localStorage.setItem('safetyCheck_settings', JSON.stringify(updatedSettings));
            onSettingsUpdate({ maintenanceMode: maintMode, maintenanceMessage: maintMessage });

            showToast(maintMode ? "SYSTEM LOCKDOWN ACTIVATED" : "System Access Restored", "success");
        } catch (e) {
            showToast("Failed to update status. Check connection.", "error");
        } finally {
            setIsSavingMaint(false);
        }
    };

    const applyTemplate = (type: 'upgrade' | 'downtime' | 'restart') => {
        if (type === 'upgrade') {
            setMsgType('info');
            setMsgBody('System Upgrade scheduled for tonight at 22:00. Brief downtime expected.');
        } else if (type === 'downtime') {
            setMsgType('critical');
            setMsgBody('Emergency Maintenance: System will be offline in 15 minutes. Please save your work.');
        } else if (type === 'restart') {
            setMsgType('warning');
            setMsgBody('Server restart initiated. Performance may be degraded for 5 minutes.');
        }
    };

    return (
        <div className="max-w-5xl mx-auto animate-fadeIn pb-12 space-y-8">
            <div className="flex items-center gap-4 mb-6">
                <div className="p-3 bg-red-600 rounded-xl shadow-lg text-white">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                </div>
                <div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">Superadmin Console</h1>
                    <p className="text-slate-500 font-medium">Global Lockdown & Security Control</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* LEFT: Broadcast Center */}
                <div className="space-y-6">
                    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z"></path></svg>
                                Global Broadcast
                            </h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <textarea 
                                className="w-full p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none min-h-[120px] text-sm text-slate-700 bg-slate-50 font-medium"
                                placeholder="Message to all active users..."
                                value={msgBody}
                                onChange={e => setMsgBody(e.target.value)}
                            ></textarea>

                            <div className="flex gap-4">
                                <div className="flex-1">
                                    <div className="flex bg-slate-100 p-1 rounded-lg">
                                        {(['info', 'warning', 'critical'] as const).map(t => (
                                            <button
                                                key={t}
                                                onClick={() => setMsgType(t)}
                                                className={`flex-1 py-2 text-[10px] font-bold rounded-md capitalize transition-all
                                                    ${msgType === t ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}
                                                `}
                                            >
                                                {t}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <button 
                                    onClick={handleBroadcast}
                                    disabled={isSending}
                                    className="px-6 bg-blue-600 text-white font-bold rounded-xl shadow-lg disabled:opacity-50"
                                >
                                    {isSending ? '...' : 'Send'}
                                </button>
                            </div>
                        </div>
                        <div className="bg-slate-50 px-6 py-3 border-t flex gap-2">
                             <button onClick={() => applyTemplate('upgrade')} className="px-2 py-1 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-600">Upgrade Template</button>
                             <button onClick={() => applyTemplate('downtime')} className="px-2 py-1 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-600">Downtime Template</button>
                        </div>
                    </div>
                </div>

                {/* RIGHT: System Lockdown */}
                <div className="space-y-6">
                    <div className={`rounded-2xl shadow-sm border transition-all ${maintMode ? 'bg-red-50 border-red-200' : 'bg-white border-slate-200'}`}>
                        <div className={`px-6 py-4 border-b flex justify-between items-center ${maintMode ? 'bg-red-100' : 'bg-slate-50'}`}>
                            <h3 className={`font-bold flex items-center gap-2 ${maintMode ? 'text-red-800' : 'text-slate-800'}`}>
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                                System Lockdown Mode
                            </h3>
                            <button 
                                onClick={() => setMaintMode(!maintMode)}
                                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${maintMode ? 'bg-red-600' : 'bg-slate-200'}`}
                            >
                                <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition ${maintMode ? 'translate-x-6' : 'translate-x-1'}`} />
                            </button>
                        </div>
                        <div className="p-6 space-y-4">
                            <p className="text-xs text-slate-600 font-medium leading-relaxed">
                                <strong>Warning:</strong> Activating Lockdown will instantly disconnect all users except SuperAdmins. Changes propagate globally within 30 seconds.
                            </p>

                            <div>
                                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Maintenance Message</label>
                                <input 
                                    type="text" 
                                    className="w-full p-3 border border-slate-300 rounded-lg text-sm font-bold bg-white"
                                    value={maintMessage}
                                    onChange={e => setMaintMessage(e.target.value)}
                                />
                            </div>

                            <button 
                                onClick={handleSaveMaintenance}
                                disabled={isSavingMaint}
                                className={`w-full py-4 rounded-xl font-bold shadow-lg transition-all
                                    ${maintMode ? 'bg-red-600 text-white' : 'bg-slate-800 text-white'}
                                `}
                            >
                                {isSavingMaint ? 'UPDATING SYSTEM...' : 'CONFIRM SYSTEM STATUS'}
                            </button>
                        </div>
                    </div>

                    <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100">
                        <h4 className="text-sm font-bold text-amber-900 mb-2">Safety Notice</h4>
                        <p className="text-xs text-amber-700 leading-relaxed">
                            Deployed applications use "Cache-Busting" logic. If lockdown doesn't appear for a user, they should refresh once. The system will automatically detect the status on its next 30-second poll.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default MaintenanceView;

