import React, { useState } from 'react';
import { User, SystemSettings } from '../types';
import { BACKEND_SCRIPT_TEMPLATE } from '../constants';

interface LoginViewProps {
  onLogin: (user: User) => void;
  appScriptUrl: string;
  setAppScriptUrl: (url: string) => void;
  settings: SystemSettings;
}

const LoginView: React.FC<LoginViewProps> = ({ onLogin, appScriptUrl, setAppScriptUrl, settings }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [showConfig, setShowConfig] = useState(!appScriptUrl); 
  const [showScriptModal, setShowScriptModal] = useState(false);
  const [isRegistering, setIsRegistering] = useState(false);
  const [fullName, setFullName] = useState('');
  const [position, setPosition] = useState('');
  const [isCopying, setIsCopying] = useState(false);
  const [logoError, setLogoError] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!appScriptUrl) {
      setError("System Database URL is missing.");
      setShowConfig(true);
      return;
    }
    setError('');
    setIsLoading(true);

    try {
      const payload = isRegistering 
        ? { action: 'register_user', username, password, name: fullName, position: position, role: 'SuperAdmin' }
        : { action: 'login', username, password };

      const response = await fetch(appScriptUrl, {
        method: 'POST',
        body: JSON.stringify(payload)
      });

      const result = await response.json();

      if (result.status === 'success') {
          if (isRegistering) {
              setError("System Owner (SuperAdmin) created! Please log in.");
              setIsRegistering(false);
              setFullName('');
              setPosition('');
              setPassword('');
          } else {
              const rawUser = result.user;
              let safeRole: User['role'] = 'Inspector';
              const rawRole = rawUser.role ? String(rawRole).trim().toLowerCase() : '';

              if (rawRole === 'superadmin') safeRole = 'SuperAdmin';
              else if (rawRole === 'admin') safeRole = 'Admin';
              else if (rawRole === 'operations') safeRole = 'Operations';
              else if (rawRole === 'maintenance') safeRole = 'Maintenance';
              else if (rawRole === 'secretary') safeRole = 'Secretary';
              else if (rawRole === 'other') safeRole = 'Other';
              else safeRole = 'Inspector';

              onLogin({ ...rawUser, role: safeRole, position: rawUser.position || '' });
          }
      } else if (result.code === 'NO_USERS') {
          setError("New Database detected. Create the System Owner account.");
          setIsRegistering(true);
      } else {
          setError(result.message || "Authentication failed.");
      }

    } catch (err) {
      setError("Connection failed. Check internet or Settings.");
    } finally {
      setIsLoading(false); 
    }
  };

  const copyScript = () => {
      navigator.clipboard.writeText(BACKEND_SCRIPT_TEMPLATE);
      setIsCopying(true);
      setTimeout(() => setIsCopying(false), 2000);
  };

  return (
    <div className="min-h-screen w-full bg-white flex items-center justify-center p-4 font-sans text-slate-600 relative overflow-hidden">
       <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-blue-50/60 blur-[100px] rounded-full pointer-events-none"></div>
       <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-emerald-50/60 blur-[100px] rounded-full pointer-events-none"></div>

       <div className="w-full max-w-[420px] relative z-10 flex flex-col items-center">

          <div className="text-center mb-8 w-full animate-fadeIn">
             <div className="w-auto h-28 mx-auto mb-6 flex items-center justify-center p-2 transition-transform duration-300 hover:scale-105">
                {settings.companyLogo && !logoError ? (
                    <img src={settings.companyLogo} alt="Logo" className="w-full h-full object-contain" onError={() => setLogoError(true)} />
                ) : (
                    <div className="flex flex-col items-center">
                        <svg className="w-16 h-16 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"></path></svg>
                        <span className="text-2xl font-black text-slate-900 tracking-tight mt-2">JUBA</span>
                    </div>
                )}
             </div>

             <h1 className="text-2xl font-bold text-slate-900 tracking-tight">
                 {settings.companyName || 'SafetyCheck Pro'}
             </h1>
             <p className="text-sm font-medium text-slate-500 mt-1">Professional Fleet Inspection Portal</p>
          </div>

          <div className="w-full bg-white p-2">
              <form onSubmit={handleSubmit} className="space-y-6">

                  {/* SERVICE ALERT BANNER: Only shows if maintenance mode is active */}
                  {settings.maintenanceMode && !error && (
                      <div className="p-4 rounded-xl bg-amber-50 border border-amber-200 animate-fadeIn mb-2">
                          <div className="flex items-start gap-3">
                              <div className="p-1.5 bg-amber-100 rounded-lg text-amber-700 mt-0.5">
                                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                              </div>
                              <div>
                                  <h4 className="text-xs font-black text-amber-900 uppercase tracking-wide">Authorized Personnel Only</h4>
                                  <p className="text-[10px] text-amber-700 font-medium leading-tight mt-1">
                                      The system is currently under maintenance. Only SuperAdmins can bypass this restriction.
                                  </p>
                              </div>
                          </div>
                      </div>
                  )}

                  {error && (
                      <div className={`p-4 rounded-lg text-xs font-bold flex items-center gap-3 border animate-fadeIn ${error.includes("created") ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                          <div className={`w-2 h-2 rounded-full shrink-0 ${error.includes("created") ? 'bg-green-500' : 'bg-red-500'}`}></div>
                          <span className="flex-1">{error}</span>
                      </div>
                  )}

                  {isRegistering && (
                      <div className="space-y-4 animate-fadeIn bg-slate-50 p-6 rounded-xl border border-slate-100 shadow-inner">
                        <div className="flex items-center gap-2 border-b border-slate-200 pb-2 mb-3">
                            <div className="bg-amber-100 text-amber-700 p-1 rounded">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.38-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z"></path></svg>
                            </div>
                            <h3 className="text-xs font-black text-slate-700 uppercase tracking-wide">System Owner Setup</h3>
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">Full Name</label>
                            <input type="text" required className="w-full px-4 py-3 bg-white border border-slate-300 rounded-lg focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none transition-all text-slate-900 text-sm font-medium placeholder-slate-400" value={fullName} onChange={e => setFullName(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-2 pl-1">Position</label>
                            <input type="text" required className="w-full px-4 py-3 bg-white border border-slate-300 rounded-lg focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none transition-all text-slate-900 text-sm font-medium" value={position} onChange={e => setPosition(e.target.value)} />
                        </div>
                      </div>
                  )}

                  <div className="space-y-5">
                      <div className="group">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">Username</label>
                          <div className="relative">
                              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg></span>
                              <input type="text" required className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-emerald-500 outline-none transition-all text-slate-900 text-sm font-bold shadow-sm" value={username} onChange={e => setUsername(e.target.value)} />
                          </div>
                      </div>
                      <div className="group">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 pl-1">Password</label>
                          <div className="relative">
                              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg></span>
                              <input type="password" required className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-emerald-500 outline-none transition-all text-slate-900 text-sm font-bold shadow-sm" value={password} onChange={e => setPassword(e.target.value)} />
                          </div>
                      </div>
                  </div>

                  <div className="pt-4">
                      <button type="submit" disabled={isLoading} className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all text-sm tracking-wide ${isLoading ? 'bg-slate-400' : isRegistering ? 'bg-blue-600 hover:bg-blue-700' : 'bg-emerald-700 hover:bg-emerald-600'}`}>
                          {isLoading ? 'VERIFYING...' : isRegistering ? 'CREATE SYSTEM OWNER' : 'SECURE LOGIN'}
                      </button>
                  </div>
              </form>

              {!appScriptUrl && !isRegistering && (
                  <div className="mt-12 text-center">
                      <button type="button" onClick={() => setShowConfig(!showConfig)} className="group flex items-center justify-center gap-2 mx-auto px-4 py-2 rounded-full bg-slate-100 hover:bg-white border border-slate-200 shadow-sm transition-all">
                          <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></span>
                          <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Connect Database</span>
                      </button>
                  </div>
              )}
          </div>

          {showConfig && (
              <div className="w-full mt-6 bg-white border border-slate-200 p-6 rounded-2xl animate-fadeIn shadow-xl relative z-20">
                  <h4 className="text-[10px] font-black text-slate-400 mb-4 uppercase tracking-widest">Database Connection</h4>
                  <input type="text" value={appScriptUrl} onChange={e => setAppScriptUrl(e.target.value)} placeholder="https://script.google.com/macros/s/..." className="w-full p-3 bg-slate-50 border border-slate-300 rounded-lg text-xs font-mono text-blue-600 mb-4 outline-none focus:border-blue-500" />
                  <button onClick={() => setShowScriptModal(true)} className="w-full py-3 bg-slate-800 text-white text-xs font-bold rounded-lg transition-colors flex items-center justify-center gap-2">View Setup Instructions</button>
              </div>
          )}
       </div>

       {showScriptModal && (
         <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full flex flex-col max-h-[85vh] overflow-hidden">
                <div className="p-5 bg-slate-50 flex justify-between items-center border-b">
                    <h3 className="font-bold text-lg text-slate-800">Backend Setup Guide</h3>
                    <button onClick={() => setShowScriptModal(false)} className="text-slate-400 hover:text-slate-700 transition p-2">✕</button>
                </div>
                <div className="p-8 overflow-y-auto bg-white">
                    <div className="prose prose-sm max-w-none text-slate-600 mb-6 font-medium">
                        <ol className="list-decimal pl-4 space-y-2">
                            <li>Create a new Google Sheet &rarr; Extensions &rarr; Apps Script.</li>
                            <li>Paste the code below, Save, and click Deploy &rarr; New Deployment.</li>
                            <li>Select "Web App", Execute as "Me", Access "Anyone".</li>
                        </ol>
                    </div>
                    <div className="relative">
                        <pre className="bg-slate-900 p-6 rounded-xl text-[10px] font-mono text-emerald-400 overflow-x-auto h-64">{BACKEND_SCRIPT_TEMPLATE}</pre>
                        <button onClick={copyScript} className="absolute top-4 right-4 px-4 py-2 bg-blue-600 text-white text-xs font-bold rounded-lg shadow-lg">{isCopying ? 'COPIED!' : 'COPY CODE'}</button>
                    </div>
                </div>
            </div>
         </div>
       )}
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect } from 'react';
import { INITIAL_DATA, InspectionData, User } from './types';
import { 
    SHEET_HEADERS, PETROLEUM_HEADERS, PETROLEUM_V2_HEADERS, ACID_HEADERS,
    INSPECTION_ITEMS, PETROLEUM_INSPECTION_ITEMS, PETROLEUM_V2_ITEMS, ACID_INSPECTION_ITEMS
} from './constants';

// Hooks
import { useAuth } from './hooks/useAuth';
import { useSettings } from './hooks/useSettings';
import { useNotifications } from './hooks/useNotifications';
import { useHistory } from './hooks/useHistory';
import { useOfflineSync } from './hooks/useOfflineSync';
import { useSubscription } from './hooks/useSubscription';

// UI Components
import Toast from './components/ui/Toast';
import Sidebar from './components/layout/Sidebar';
import ReportViewerModal from './components/ui/ReportViewerModal';
import SubmissionOverlay from './components/ui/SubmissionOverlay';
import ProfileModal from './components/ui/ProfileModal';
import NotificationCenter from './components/ui/NotificationCenter'; 
import UpgradeModal from './components/ui/UpgradeModal';
import InspectionStartModal from './components/ui/InspectionStartModal';
import SubscriptionAlert from './components/ui/SubscriptionAlert';
import MaintenanceOverlay from './components/ui/MaintenanceOverlay';
import RequestInspectionModal from './components/ui/RequestInspectionModal'; 
import OnboardingWizard from './components/ui/OnboardingWizard'; 
import SystemTour from './components/ui/SystemTour'; 
import InstallPwaPrompt from './components/ui/InstallPwaPrompt';

// Views
import LoginView from './views/LoginView';
import SettingsView from './views/SettingsView';
import GeneralDashboard from './views/GeneralDashboard';
import PetroleumDashboard from './views/PetroleumDashboard';
import PetroleumV2Dashboard from './views/PetroleumV2Dashboard';
import AcidDashboard from './views/AcidDashboard';
import UserManagementView from './views/UserManagementView';
import OverviewDashboard from './views/OverviewDashboard';
import InspectionFormView from './views/InspectionFormView';
import SupportView from './views/SupportView';
import MaintenanceView from './views/MaintenanceView';
import RequestTrackingView from './views/RequestTrackingView';

// Report Components
// Fix: Import missing printable report components used in the viewer modal
import PrintableGeneralReport from './components/reports/PrintableGeneralReport';
import PrintablePetroleumReport from './components/reports/PrintablePetroleumReport';
import PrintablePetroleumV2Report from './components/reports/PrintablePetroleumV2Report';
import PrintableAcidReport from './components/reports/PrintableAcidReport';

const App = () => {
  const { currentUser, setCurrentUser, handleLogin, handleLogout, sessionExpired, setSessionExpired } = useAuth();
  const { settings, setSettings, appScriptUrl, setAppScriptUrl, isSavingSettings, handleSaveSettings } = useSettings();
  const { subscription } = useSubscription(appScriptUrl, currentUser);

  const [activeModule, setActiveModule] = useState('overview'); 
  const [viewMode, setViewMode] = useState<'dashboard' | 'form'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error' | 'info' | 'warning'} | null>(null);
  const [isRequestModalOpen, setIsRequestModalOpen] = useState(false);

  const { historyList, isLoadingHistory, validationLists, stats, fetchHistory } = useHistory(appScriptUrl, activeModule, currentUser);

  const showToast = (message: string, type: 'success' | 'error' | 'info' | 'warning') => {
      setToast({ message, type });
      setTimeout(() => setToast(null), 4000);
  };

  useEffect(() => {
      if (sessionExpired === 'idle') showToast("Session expired due to inactivity.", 'warning');
      else if (sessionExpired === 'max_duration') showToast("Session limit reached. Log in again.", 'info');
      if (sessionExpired) setSessionExpired(null);
  }, [sessionExpired]);

  const { submissionStatus, setSubmissionStatus } = useOfflineSync(appScriptUrl, showToast, () => fetchHistory(true));
  const { notifications, handleMarkNotificationRead, handleDismissNotification, handleClearAllNotifications } = useNotifications(appScriptUrl, currentUser, showToast);

  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [selectedReportData, setSelectedReportData] = useState<InspectionData | null>(null);
  const [formInitialData, setFormInitialData] = useState<InspectionData>(INITIAL_DATA);

  // --- CRITICAL MAINTENANCE LOGIC ---
  const isSuperAdmin = currentUser?.role === 'SuperAdmin';
  const showMaintenance = settings.maintenanceMode && currentUser && !isSuperAdmin;

  const startFreshInspection = (module: string, prefill?: Partial<InspectionData>) => {
      setFormInitialData({ ...INITIAL_DATA, timestamp: new Date().toISOString(), inspectedBy: currentUser?.name || '', ...prefill });
      setViewMode('form');
  };

  const handleExitForm = (savedData?: InspectionData) => setViewMode('dashboard');

  const handleGoogleSheetSubmit = async (formData: InspectionData) => {
    setSubmissionStatus('submitting');
    // Actual submission logic handled in useOfflineSync
    setSubmissionStatus('success');
    setTimeout(() => setViewMode('dashboard'), 2000);
  };

  const handleViewReport = (item: InspectionData | null) => {
    setSelectedReportData(item);
    setIsReportModalOpen(true);
  };

  // 1. PRIMARY: If not logged in, show Login (Allows SuperAdmin to authenticate)
  if (!currentUser) {
      return (
          <>
            <InstallPwaPrompt />
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
            <LoginView 
                onLogin={handleLogin} 
                appScriptUrl={appScriptUrl}
                setAppScriptUrl={setAppScriptUrl}
                settings={settings}
            />
          </>
      );
  }

  // 2. SECONDARY: If logged in but NOT SuperAdmin during Lockdown
  if (showMaintenance) {
      return (
        <>
           <MaintenanceOverlay isActive={true} message={settings.maintenanceMessage || ''} onLogout={() => handleLogout()} />
           {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        </>
      );
  }

  // 3. TERTIARY: Standard App Access
  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 relative">
      <SubmissionOverlay status={submissionStatus} />
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {isProfileModalOpen && (
          <ProfileModal 
            user={currentUser} 
            appScriptUrl={appScriptUrl} 
            onClose={() => setIsProfileModalOpen(false)} 
            showToast={showToast} 
            onUpdateSuccess={(u) => setCurrentUser(u)} 
          />
      )}

      <RequestInspectionModal
          isOpen={isRequestModalOpen}
          onClose={() => setIsRequestModalOpen(false)}
          onSubmit={() => {}}
          validationLists={validationLists}
          currentUserRole={currentUser.role}
      />

      <div className="relative z-10 bg-gray-50 min-h-screen">
          <Sidebar 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
            activeModule={activeModule}
            onSelectModule={(m) => { setActiveModule(m); setViewMode('dashboard'); }}
            settings={settings}
            user={currentUser}
            onLogout={() => handleLogout()}
            onEditProfile={() => setIsProfileModalOpen(true)}
            subscription={subscription} 
          />

          <div className="lg:pl-64 min-h-screen flex flex-col">
            <SubscriptionAlert subscription={subscription} user={currentUser} onManage={() => setActiveModule('settings')} />

            <header className="bg-emerald-950 border-b border-emerald-900 sticky top-0 z-40 shadow-sm">
              <div className="px-4 py-3 flex justify-between items-center text-white">
                <div className="flex items-center gap-3">
                    <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1 hover:bg-slate-800 rounded">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"></path></svg>
                    </button>
                    <h1 className="text-lg font-bold">{activeModule.toUpperCase()}</h1>
                </div>

                <div className="flex items-center gap-3">
                    <NotificationCenter 
                        notifications={notifications}
                        onMarkAsRead={(id) => handleMarkNotificationRead(id)}
                        onDismiss={handleDismissNotification}
                        onClearAll={handleClearAllNotifications}
                    />
                </div>
              </div>
            </header>

            <main className="flex-1 p-4 md:p-8 max-w-6xl mx-auto w-full">
                {viewMode === 'form' ? (
                    <InspectionFormView 
                        initialData={formInitialData}
                        activeModule={activeModule}
                        validationLists={validationLists}
                        settings={settings}
                        onSaveDraft={handleExitForm} 
                        onExit={() => setViewMode('dashboard')} 
                        onSubmit={handleGoogleSheetSubmit}
                        submissionStatus={submissionStatus}
                        onViewReport={handleViewReport}
                    />
                ) : (
                    <>
                        {activeModule === 'overview' && <OverviewDashboard appScriptUrl={appScriptUrl} onNavigate={setActiveModule} userRole={currentUser.role} />}
                        {activeModule === 'settings' && <SettingsView settings={settings} setSettings={setSettings} appScriptUrl={appScriptUrl} setAppScriptUrl={setAppScriptUrl} handleSaveSettings={handleSaveSettings} isSavingSettings={isSavingSettings} showToast={showToast} user={currentUser} />}
                        {activeModule === 'maintenance' && isSuperAdmin && <MaintenanceView user={currentUser} appScriptUrl={appScriptUrl} settings={settings} onSettingsUpdate={(s) => setSettings(p => ({...p, ...s}))} showToast={showToast} />}
                        {activeModule === 'general' && <GeneralDashboard stats={stats} startNewInspection={() => startFreshInspection('general')} fetchHistory={fetchHistory} isLoadingHistory={isLoadingHistory} historyList={historyList} onViewReport={handleViewReport} onPrint={() => {}} />}
                        {activeModule === 'petroleum' && <PetroleumDashboard stats={stats} startNewInspection={() => startFreshInspection('petroleum')} fetchHistory={fetchHistory} isLoadingHistory={isLoadingHistory} historyList={historyList} onViewReport={handleViewReport} onPrint={() => {}} />}
                        {activeModule === 'petroleum_v2' && <PetroleumV2Dashboard stats={stats} startNewInspection={() => startFreshInspection('petroleum_v2')} fetchHistory={fetchHistory} isLoadingHistory={isLoadingHistory} historyList={historyList} onViewReport={handleViewReport} onPrint={() => {}} />}
                        {activeModule === 'acid' && <AcidDashboard stats={stats} startNewInspection={() => startFreshInspection('acid')} fetchHistory={fetchHistory} isLoadingHistory={isLoadingHistory} historyList={historyList} onViewReport={handleViewReport} onPrint={() => {}} />}
                        {activeModule === 'users' && <UserManagementView currentUser={currentUser} appScriptUrl={appScriptUrl} showToast={showToast} validationLists={validationLists} settings={settings} />}
                        {activeModule === 'support' && <SupportView appScriptUrl={appScriptUrl} currentUser={currentUser} showToast={showToast} settings={settings} validationLists={validationLists} />}
                        {activeModule === 'track_requests' && <RequestTrackingView appScriptUrl={appScriptUrl} currentUser={currentUser} showToast={showToast} />}
                    </>
                )}
            </main>
          </div>
      </div>

      {isReportModalOpen && selectedReportData && (
          <ReportViewerModal 
            onClose={() => setIsReportModalOpen(false)} 
            onPrint={() => window.print()}
            title={`Report_${selectedReportData.truckNo}_${new Date(selectedReportData.timestamp).toLocaleDateString()}`}
          >
              {activeModule === 'petroleum' ? (
                  <PrintablePetroleumReport data={selectedReportData} settings={settings} />
              ) : activeModule === 'petroleum_v2' ? (
                  <PrintablePetroleumV2Report data={selectedReportData} settings={settings} />
              ) : activeModule === 'acid' ? (
                  <PrintableAcidReport data={selectedReportData} settings={settings} />
              ) : (
                  <PrintableGeneralReport data={selectedReportData} settings={settings} />
              )}
          </ReportViewerModal>
      )}
    </div>
  );
};

